INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (1,1,1,'TUR[k]MEN

BIRINJI BÖLÜM Köne güzerler 1. TUR[k]MEN (“türkmen” sözüniň gelip çykyşy barada) Bu mesele boýunça alymlar dürli döwürlerde, dürli çaklamalary orta atdylar. Hususan-da, onuň ―türk manend‖, ―tir-keman‖, türk-iman‖ diýen ýaly sözlerden emele gelendigini, şeýle hem onuň ikinji ―men‖ böleginiň manysynyň belli bolup, birinji ―türk‖ böleginiň näbellidigini aýtdylar. Şol näbelli bölegiň aslyny biz gadymyýetde biziň şu günki ýaşaýan topragymyzyň çäklerinde, Turanda ýaşan ―turlardan‖, ýagny, ―tur‖ sözünden gözlemekligi makul bildik. A. Meredow bilen S. Ahallynyň ―türkmen klassyky edebiýatynyň sözlügi‖ [1] atly kitabynda ―tur‖ sözüne üç hili düşündiriş berilýär, emma, ol sözüň manysy, gelip çykyşy barada hiç zat aýdylmaýar. Turlar barada maglumat berýän iň gadymy çeşme, otparazçylyk dininiň mukaddes kitby bolan Awestany gadymy awesta dilinden ors diline terjime eden Iwan Steblin-Kamenskiý hem şol kitaba ýerleşdiren sözlüginde ―tur‖ sözüne düşündiriş bermändir. Ol diňe: ―Turlar-turanlylar daýhançylyk bilen meşgullanýan çarwa taýpalar‖ [2], diýmek bilen çäklenipdir. ―Tur‖ sözüniň manysyna biz gadymy türki dillere bagyşlanan ―Drewniý týurskiý slowar‖ atly sözlükde-de, Mahmyt Kaşgarlynyň meşhur ―Diwany lugat-at Türk‖ atly ylmy işinde-de duş gelmedik. Asyl-ha, ol ýerde ―tur‖ sözi ýok. Bu bolsa bizde: Bu söz türki asylly däl bolaýmasyn, diýen şübhe döretdi. Edil, ―tur‖ sözüniň düşündirilişine, ýer-ýurt atlaryny öwreniji S. Atanyýazowyň sözlünlerinde-de gabat gelmedik. Ol: ―tur‖ sözüniň etnik ylmy dünýä belli däldigini nygtaýar. Ýöne, özüniň ―Şejere‖ atly kitabynyň ―türk‖ sözüne düşündiriş berýän bölüminde, ―türk‖ sözüni ikä bölmek arkaly ―tur‖ sözüne hem gyltyzraga-da degip geçýär. Ol öňürti ―türk‖ sözi barada ýazylan ähli işleri bir ýere jemläp, ýörite makala ýazan A. N. Kononowyň nuktaý nazaryny beýan edýär. Ýagny, onuň ―türk‖ sözüni ―tur‖ we ―k‖ görnüşinde iki bölendigini, şeýle hem şonuň

1',1922);
INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (2,1,2,'birinji böleginiň başda ―Hudaý‖, ―Alla‖ diýen bolup, soň hormatly orny töri aňladdandygyny, ahyram güýç, kuwwat, hojaýyn ýaly düşünjelere eýe bolandygyny, ikinji ―k‖ böleginiň bolsa köplük goşulmasydygyny subut etmeklige çalyşandygyny belleýär. Soňra onuň özem A. N. Kononowyň derňew usulyna eýerip, ―türk‖ sözün ―ti‖ hem-de ―rk‖ görnüşindeikä bölýär we şonuň birinji bölegi türki halklarynyň gadymy etniki ady bolsa gerek, diýen iňňän dogry netijä gelýär we manysyny düşündirmese-de, tüýs biziň eşidesimiziň gelýän sözümiziň üstünden barýar. Soňra ol ―tur‖ sözüniň yzyna goşulan, köplügi aňladýan ―k‖ goşup, ony ―topar‖ ―taýpa‖ ―il‖ manysyndaky tüg/tü sözünden we yzly-yzyna goşulan, köplügi aňadýan ―r‖ hem-de ―k‖ goşulmasyndan hasyl bolup, ―taýpa‖ topar‖, ―il‖ manysynda ýüze çykypdyr, diýmek bilen, çözgütden ýene-de sowa düşýär. [3]. Şeýlelikde, ―tur‖ sözüniň asyl manysy ýene-de öňküsi ýaly, nämälimligine galýar. Şonuň üçinem biz ýene-de ―tur‖ sözi türki asylly däl bolaýmasyn diýen pikirimize dolanyp geldik we gadymyýetde turlar bilen goňşy oturan, eýran dilli halklar ýaly indoýewropa dil maşgalasyna girýän ors diliniň W. Dal tarapyndan işlenip düzülen sözlügine ýüzlendik. Ol ýerde ―tur‖ sözüne iki hili düşündiriş berlipdir. 1. Bir aýlaw. (Bir aýlaw tans, küşt oýnunyň ikinji aýlawy we ş.m.) 2. Tohumy ýitip giden ýabany öküz. ―Tur‖ sňzüne berilýän hut şu hili düşündirişe biz ―Uly orsçatürkmençe sözlükde‖ [4] hem gabat geldik. Diýmek, tur – öküz. Şonuň bilen birlikde-de, ol halkyň ady. Eýsemde bolsa, taryhyň çal saçlarynyň arasyna siňip giden şol halk haýsy halk? Olar kimler? Kimleriň ata-babalary? Türkmenleriň ata-babalary bolan oguzlaryň adynyň ―öküz‖ sözünden gelip çykandygy baradaky düşünje türkologlaryň aglabasy tarapyndan bireýýäm ykrar edildi. Özümiziňem şol düşünjä gol ýapýandygymyz üçin ―tur‖ sözüniň öküzlere – oguzlara goňşy, eýran dilli halklar tarapyndan dakylan ikinji atdyr diýip pikir edýäris, ýagny: öküz – awtoetninim, tur – alloetnonim. Diýmek, meşhur Awestadaky turlar, şu günki türkmenleriň atababalary bolan oguzlar – öküzler bolmaly. Halkyň öz adynyň we daşardan dakylan adynyň bolýandygyna tymsaly biz daşdan gözlemeli däl. Mysal züin Germaniýa – bu, onuň daşardan dakylan ady. Öz ady – Doýçland. Halkyň

