INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (3,1,3,'adyna biz orslardan eşidip ―nemes‖ diýýäris. Emma özleri – ―doýç‖ diýýärler. Ýa-da Gruziýa (Gürjüstan). Bu hem oňa daşardan dakylan at. Öz ady: Sakartweli. Şeýle mysallar başga-da köp. Turlaryň öküzlerdigini, oguzlardygyny Ferdöwsiniň meşhur ―Şanama‖ eseri hem tassyk edýär. Ol ýerde hem edil Awestadaky ýaly turlar bilen arileriň arasyndaky taryhy hereketler beýan edilýär. Şonda turlaryň serkerdesi - Afrasyýan (Awestada Afanhrasýan). A. Meredow bilen S. Ahallynyň agzalan sözlüginde bolsa, Afrasyýabyň ähli türki halklaryň nesilbaşysydygy aýdylýar.

