INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (5,1,5,'aňladýar, ―ist‖ – durmak, bir zadyň duran, üýşen ýeri, ―an‖ – mesgeni, ýurdy aňladýar. Ýagny: türkileriň, türkmenleriň üýşen, toplanan ýeri, ýurdy, mesgeni, watany.

