INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (9,1,9,'Bu bolsa öküzleriň – turlaryň öz asly mekanlary bolan Öküz (Tejen) derýasynyň boýunda we soňraky süýşen ýerlerinde ariler bilen medeni we etniki taýdan garyşyp-gatyşandyrlar diýmäge doly esas berýär. Çünki, oguzlar Öküz derýasynyň boýundan miladydanöňki IVmüňýyllykda giden bollaýanlarynda-da, indoiranlaryň asly mekanlaryndan örňäp Eýrana we Orta Aziýa aralaşan döwürlerine gabat gelýär. Eger-de oguzlar käbir alymlaryň çak edişi ýaly, Öküz derýasynyň boýundan miladydanöňki II müňýyllykda giden bolsalar, onda-ha olar bu ýerde ariler bilen tas, iki müň ýyla golaý garyşyp-gatyşyp oturandyrlar diýip oýlanmaga mümkinçilik döredýär. Aslynda turlar-öküzler nämüçin Öküz derýasynyň boýundan gitdilerkän? Biziň pikirimizçe, bu zatlaryň aňyrsynda düşnükli hadysa ýatyr. Ýagny, ariler täze dini-taglymatlary-zoroastrizmi döredýärler. Turlar bolsa oňa uýmaýarlar. Olaryň öz totomlary bar: Asman, Gün, Aý, Ýyldyz. Dogry, şol zatlara arilerem uýýarlar. Hatda Awestada şol zatlaryň hersine bagyşlanan ýörite gimnleri hem bar. Ýöne otparazçylyk dinini esaslandyryjy Zaratuştra şolaryň ählisini bir ýere jemläp, olary ýeke-täk Hudaýyň – Ahura – Manýanyň garamagynda goýýar. Ot – Hudaýyň ogly diýip yglan edýär. Aýam, GünemÝyldyzlaram, ýer-suwam diňe Ahura – Mana uýan adama hyzmat eder, uýmadygy betbagtçylyga uçradar diýen düşünje ýaýradýar. Olar üçin kim Ahura – Mana uýmasa, jyna-arwaha gol beren, döwlerden sapak alan, tersa, has takygy dünýädäki ähli gowluklaryň we hakykatyň duşmany bolan Anhra – Manýanyň şägirdi. Olar üçin turlaram şeýle. Awestada olar hatda turlaryň watanynam – döwleriň, arwahlaryň mekany hökmünde suratlandyrýarlar. Hut şonuň üçinem, tur serkerdesi Afrasyýabya mukaddes Hwarnony ele salmak başardanok. Awestany öwreniji alymlar tarapyndan häzirki Aral deňzidir öýdülýän Worokuşa deňziniň düýbünde gizlengi ýatan, ele salan bol suwly, mes toprakly, bol suwly ýerlere, mala, baýlyga eýe edý