INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (10,1,10,'örňemeklerini käbir alymlar miladydanöňki II müňýyllygyň ahyrlarynda ýüz beren gurakçylyk sebäplidir öýdýärler. Ýöne, şol gurakçylygyň Öküz derýasynyň Eýran tarapdan bilkastlaýyn beklenmegi zerarly bolandygyny çak edýänlerem bar. Turlar bilen arileriň arasynda täze din zerarly düşen gapmagarşylygy nazarda tutsaň, soňky çaklama hakykata has golaý görünýär. Bu ýerde-de geň galyp oturasy iş ýok. Islendik din dünýä inende ägirt uly garşylyklara sezewar bolýar. Çünki, din – bu külli adamzat möçberindäki syýasy öwrülişik. Öňki din hem öz ornuny ―mesaňa‖ diýäge-de beräýenok. Asyrlarboýy beýnisinde berç bolan köne ynanjy adamlaryň aňyndan çykarmagam aňsat däl. Hut, şonuň üçinem, täze dini ýaýradyjylar, hususanda onuň pygamberleri, köplenç öňki ynanja uýýanlaryň pidasy bolupdyr. Zaratuştranyň özem Hudaýa mynajat edip duran wagty, pyçaklanylyp öldürilipdir. Isa pygamber bolsa haça çüýlenipdir. Muhammet pygamber birnäçe kynçylyklara sezewar edilipdir. Öňki ynanjy gorap, täze dine garşy baş göteren Afrasyýabyň, külli tur halkynyň şol, taryhy hereketlerem tebigy, kanunalaýyk ýagdaýdyr we türkmenleriň gadymyýetde otparazçylyk dinine uýandyklary baradaky pikir iňňän şübhelidir. Bu – şol bir territoriýada haýsy möwrütde haýsy halkyň mekan tutandygy bilen baglydyr. Galyberse-de, öküzleriň – turlaryň Öküz derýasynyň boýundan otparazçylyk dini döremezden öň giden bolmaklaram mümkin. Çünki, Änewden, Göksüýriden Mesopotizmiýa gidip, soň ol ýerde şumerler-sümerler adyny alan halklaram bu ýerden hut şol döwürler ýagny, otparazçylyk dini döremezden öň giden hasap edilýär. Bu-da hususan, arileriň şu topara aralaşan döwrüne gabat gelýär. Ýöne, her näme bolaýandada turlar Gündogara tarap süýşselerem öz taryhy örülerinden – Turandan çykyp gidenoklar. Asylha-da arilerem turlaram, Eýranam, Turanam biri-birine gaty bir ýat halk ýa ýat ýurt däldir. Olaryň ikisem Eýran, Turan atly taryhy, mähnet gazanyň