INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (12,1,12,'XIV asyr musul Man taryhçysy Fazlallah Reşideddin, XVI asyr türkmen taryhçysy Salyr Baba Gulaly ogly ýaly bilermenleriň ―Oguznamalary‖ hem Nuh pygamberden başlanýar. Abylgazynyň ýazmagyna görä, Adam atadan Nuh pygambere çenli on arka bar: şiş – Berd – Yhnuh (Idris) – Mutawyşlyk – Leýmek – Nuh. Tupandan soň Nuh pygamber adam tohumy ýitmez ýaly, Ham, Sim, Ýafys atly üç oglunyň hersini ýeriň bir künjüne iberipdir. Kiçi ogly Ýafysa (Ýafet) zeminiň kutby-şemal tarapy, şindiki Türküstan ýurdy düşüpdir. Ýafys nesli dokuz arka aýlanandan soň Oguz döräpdir. Şerejäniň zynjyr düzümi şu şekilde: Ýafys – Türk – Tütek – Emleje – Dip – Bakuý – Gök han – Alynja – Tatar – Mogul atly ekizler, – Moguldan Gara han, Gara handan – Oguz. Oguzdan alty ogul önüp ösýär. Ine, hut şu ýerdenem oguz taryhy bilen Bütindünýä rowaýatlarynyň arasyndaky meňzeşlikler ýüze çykyp başlaýar. ―Oguznamanyň‖ uýgur wariantynda meňzeşlik has hem golaýlaşýar. Ýagny, beýleki ―Oguznamalarda‖ Oguz hanyň alty oglunyň altysam ýönekeý oguz gyzlaryndan bolan bolsa, bu wariantda edil ýunan rowaýatlarynda alty ogluň Asman bilen Zeminiň, ýagny Uran bilen Geýanyň nikasyndan bolşy kimin Oguz hanyň ogullarynyňam üçüsi şöhle bilen ýere inen asman perisinden, üçüsem zemin gözelinden bolýar. Ýöne, bu entek diňe san babatdaky meňzeşlik. Indi bolsa Oguz hanyň ogullarynyň we gadymy ýunan hudaýlarynyň atlaryndaky meňzeşliklere garap geçeliň. Uranyň bir ogly – Okean. Oguz hanyň bir oglunyň ady Deňiz. Uranyň ogly Gipperiondan we Teýadan Gün hudaýy Gelios, Aý hudaýy Selena döreýär. Oguz hanyňam bir oglunyň ady Gün, ýagny Gün han, ýene bir oglunyň ady Aý. Aý han. Uranyň başga bir oglunyň ady Astreýa. Bu ýunan dilinde Astron sözünden bolup, ýyldyz diýmekligi aňladýar. Şeýlelikde, o-da Oguz hanyň Ýyldyz, ýagny Ýyldyz han atly ogly bilen atdaşdyr. Indi bolsa Oguz hanyň ogullary bilen atdaş çykan dört sany ýunan hudaýynyň atasy Uranyň öz adyny