INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (14,1,14,'öňki IV müňýyllygyň ortalarynda, entek Aşaky hem Ýokarky Müsür şalyklary emele gelmezinden öň, Geliopolyň žresleri jümle-jahany asman hudaýlarynyň ýaradandyklary baradaky öz pikirlerini orta atypdyrlar. Hatda iki şalyk emele gelenden soňam, şu barada olaryň hersi öz wersiýalaryny işläp düzüpdirler. Olaryň hersi öz hudaýlaryny älem-jahany ýaradyjy ýeketäk, ähli hudaýlaryň atasy hökmünde, özlerini hem şol hudaýlaryň mirasdüşeri, adamzadyň başy hökmünde görkezmäge çalşypdyrlar. Iki şalyk birigip, bir döwlete öwrülenden soňam, jümle-jahanyň ýaradylyşy barada Müsüriň medeni merkezleri bolan Germopolyň, Geliopolyň, Memfisiň hersinde bir dürli pikir aýdylypdyr. Mysal üçin Geliopolyň žresleri dünýäni Gün hudaýy Ra ýaradypdyr diýer wersiýany işläp düzüpdirler. ―Piramidalar tekstiniň‖ habar bermegine görä, Ra öz-özüni Nun atly Haosdan – ilkinji okeandan ýaradypdyr. Ra şondan soň özi üçin aýak basar ýaly ―Ben-ben‖ atly depe döredipdir we şol adajykda durubam, beýleki eli bilen asman hudaýlaryny ýaradyp başlapdyr. Älem içre ýalňyz özi bolansoň, hudaýlaryň ilkinji jübütini – Şu (howa) we Tefnut (çyglyk) atly hudaýlary Ranyň özi dogurmaly bolupdyr. Şol jübütden Ýer hudaýy Geba, asman hudaýy Nun doglupdyr. Öz gezeklerinde olaram iki jübüt hudaýlary: Osirisi we Seti, şeýle hem Isidany we Neftidany dogrupdyrlar. Düzüjileriň ündewlerine görä, Ra asmandaky ähli hudaýlaryň we ýer ýüzündäki barça janly-jemendeleriň hökümdary bolupdyr. Görşümiz ýaly, Hudaýlar baradaky döwlet strukrutasy görnüşinde düzülen müsür rowaýatlary hem edil ýunan rowaýatlary hem-de oguz taryhynyň gözbaşy kimin şol bir asman, Gün, Okean, toprak, şeýle hem ilkinji Haos bilen baglanyşykly. Bu düşünjeleriň hemmesiniň aňyrsynda gadymyýetde bolup geçen güýçli tebigy hadysalar, weýran ediji suw joşgunlary, älem-jahany ýakypýandyryp barýan güýçli ýangynlar, ölüm howply gurakçylyklar we beýleki tebigy hadysalar, şol hadysalary