INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (15,1,15,'jisimlerini hudaý tutunypdyrlar, guran döwletlerini berkitmek üçin özlerinem, özlerine we nesillerine goýýan atlarynam, gelip çykyşlarynam asmana, asman jisimlerine, şeýle hem heýhat getiriji suwa, sile, gaýnag pürküji daglara golaý edip görkezmek isläpdirler. Öň her haýsy bir jandara ýa jisime uýup ýören bölek-bölek taýpalary, halkyýetleri bir döwlete birikdirmek, bir agyza bakdyrmak üçin umumy hudaýlary oýlap tapmak we olar barada dürli-dürli rowaýatlaryň täze-täze wersiýalaryny işläp düzmek zerurlygy ýüze çykypdyr we bu zatlar belli bir derejede döwlet möçberindäki syýasy ähmiýete eýe bolupdyr. Şonuň üçinem hatda özüni Hudaýyň ogly diýip yglan eden patyşalaram bolupdyr. Halk hem olara ynanypdyr. Çünki, o döwürler entek olar Hudaýyň ýeke-täkdigine akyl ýetirip bilmändirler. Hut şonuň üçinem, dagynyklyk adamzadyň başynda uzak wagtlap dowam edipdir. Käte bir hudaýlyga çagyrýan adamlar – resullar peýda bolupdyr. Emma rowaýatlara görä, halklaryň agyzlarynyň birleşmegini islemedik hökimdarlar halkyň isleggine-de, Hudaýyň birligine-de garşy gidipdirler. Hudaýyň resullaryny jezalandyrypdyrlar. Netijede ýer ýüzünde azgynçylyk köpelipdir. Resullar bolsa ýene-de peýda bolupdyrlar. Ýene-de Hudaýyň birligini ündäpdirler. Ahyrsoňy bolmandan soň Hudaý öz resullaryndan özge ähli adamlara gazap edipdir. Ýer ýüzüni suw alypdyr, Gün ýakypdyr, daglar lerzana gelipdir. Bu baradaky rowaýat müňlerçe ýyllap adamlaryň aňynda ýaşapdyr. Çünki, düýbi çynam bolsa, ýalanam bolsa, ol ynanjyň Mantyky Manysy uly bolupdyr. Ýagny, azgynçylyk etmeli däl, tebigatyň, Hudaýyň garşysyna gitmeli däl, onuň birligini inkär etmeli däl. Eger-de şu zatlary berjaý etmeseň, Asman, Zemin bilen ylalaşykly ýaşamasaň, Hudaý seni öz gazabyna duçar eder. Her niçik-de bolsa wagtyň geçmegi bilen jemgyýet özgeripdir, adamlaryň aňy ösürdir, öňki ynanç, ygtykat, din, belli-belli möwritleriň geçmegi bilen könelipdir, täze ygty