INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (17,1,17,'Ýyldyza uýup ýören owşarlary, kazyklary, bekdilileri, garkynlary; Göge (Asmana) uýup ýören baýandyrlary, bejeneleri, çawuldyrlary, jebnileri; Daga uýup ýören salyrlary eýmürleri, bükdüzleri, ýiweleri, kynyklary bir ýere birleşdirip, harby taýdan güýçli oguzlar döwletini döreden bolsa gerek. Biziň pikirimizçe, Oguz hanyň reformasy döwründe oguzlaryň urany – ―öküz‖ hem ―gök böri‖ bilen çalşyrylýan bolmaly. Bu ýagdaý oguzlaryň gadymy mekanlaryndan çykyp, Mongol, Hytaý serhetlerine aralaşandyklaryny we ýerli şertlere görä, täze bir syýasy zerurlygyň ýüze üykandygy bilen bagly bolmagy mümkin. Çünki, gadymy Hytaýda hem Asmana uýupdyrlar. Çingiz han hem özüni ―Asmanyň ogly‖ diýip atlandyrypýan eken. Bu oguzlaryň Hytaýa ýa mongollara eden täsirimi ýa olaryň oguzlara eden täsirimi, ony aýtmak kyn, ýöne, ―böri‖ bilen baglanyşykly mesele welin köp babatda oguzlaryň täze goňşularynyň täsiri bilen baglanyşyklydyr. Oguz hanyň hem-de onuň ogullarynyň Asman we Zemin jisimleri arkaly hudaýlaşdyrylmagy hem edil ýunan, müsür döwletlerinde bolşy ýaly, täze döwlet gurluşygy bilen baglydyr. Ýöne, oguzlaryň Oguz handan kän uludygy, kosmiki güýçler baradaky ynanjyň, ygtykadyň oguzlaryň aňyna Oguz handan kän öň girendigini, olaryň Oguz handan öňem kosmiki güýçleri, Aýy, Güni, ýyldyzlary, umuman Asmany penalandyklary, ýer jisimlerini, käbir haýwanlary totam tutunandyklary gürrüňsizdir. Oguz hanyň esasy hyzmaty bolsa, olaryň ählisini bir bir ynanja birikdirendigi, şeýdibem bir bitewi döwlet döredenligi bilen baglydyr. Oguz han döwründe oguzlaryň Asmana – Göge uýandyklary, gök börini uran edinendikleri barada jedel bolup bilmez. Çünki, bu barada Oguz hanyň özi aýdyp dur.

