INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (34,1,34,'Biziň aňrymyzy has irki halkyýetlere – mundan otuz müň ýyl ozal Alýaskanyň üsti bilen Amerika kontinentine aşan halklara – häzirki indeýlere dahylly etjek bolup ýörenlerem bar. Emma soňky wagtlarda käbir türkmen alymlary düýbünden başga pikiri öňe sürdüler. Olardan Marat Durdyýew türkmenleriň aňyrsynyň arilere, şumerlere-hä däl, eýsem oguzlara-da doly derejede dahylly däldigini, şol sebäpdenem türkmen halkynyň gadymy mekanyny Talasdan, Selengadan, Altaýdan ýa Sibirden däl-de, hut şu toprakdan, köküni bolsa dah, massaget, alan, as, girkan, margian, parfian ýaly gadymy, eýran dilli ýerli halkyýetleriň kökünden gözlemelidigini tüýs ýürekden syzdyrsa, görnükli etnograf Ata Jykyýew onuň pikirini umuman goldaýar, emma türkmen halkynyň kemala gelmeginde oguzlaryň ikinji derejeli rol oýnandygy baradaky pikir bilen welin ylalaşmaýar. Garaz, pikir, garaýyş kän. Emma bu howply hadysa däldir. Gaýtam gowudyr. Çünki näbelli meseleler elmydama-da jedelli çekeleşikler, gözlegler arkaly çözülýändir. Eýsem bu çaklamalaryň haýsysy dogruka? Muňa çürt-kesik jogap bermek kyn. Ýöne, gürrüňlerine goşulýandygymyz üçin alymlardan ötünç soramak bilen, her-hal öz bildigimizi aýdyp geçmekligi ýüregimize düwdük. Taryh hronologiki yzygiderliligi gowy görýär. Şonuň üçinem biz şu çaka çenli dowam edip gelen: Oguzlar gadymy türki taýpalardan gelip çykypdyr, diýen düşünjäni ýüzugra ret edip, oguzlary gadymy türki taýpalardan has irki zamanlara geçirýäris. Şeýlede bolsa oguzlar barada ―Oguznamadan‖ başgsa göze dürtülip duran taryhy çeşmäniň ýokdugyna görä, oguz taryhyny türkiler taryhynyň üsti bilen aýlap almaga mejbur bolýarys. Türkiler barada gürrüň etmek üçin bolsa, hökmany suratda hunlaryň, gunlaryň taryhyna ýüzlenmeli. Eýsem hunlar kim? Hunlar – dürli taýpalardan emele gelip, moladydan öňki II asyrda kuwwatly döwlet guran gadymy halkyýetdir. Şol dwürler olar hytaý bilen ýanaşyk ýatan giň sährada ýaşap