INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (37,1,37,'Aşynanyň ornaşan ýerinde gelip çykyşlary boýunça hunlardan bolan, soň ―türki dil‖ adyny alan dilde gepleýän, ―L.N.Gumilewiň aýtmagyna görä, Sary deňziň boýundan örňän gaýdan dürli taýpalar ýaşaýan ekeni. Aşynanyň ―bäş ýüz öýlüsi‖, ýagny türkütler , ana şol ýerli aborigenler bilen garyşypdyrlar we ýüz ýyl geçip-geçmänkä hytaýlylar tarapyndan özlerine dakylan ―tu-kýu‖/türküt, türk/ adyny olaryňam boýunlaryna atypdyrlar. Emma olara juda azdyklary üçin özlerem ýerli halkyň dilini kabul edip alypdyrlar. Görşümiz ýaly, asly hytaýlylardan, hunlardan, sýanbilerden bolan Aşynaňkylar öz atlaryny, asly hunlardan bolan aborigenler bolsa öz dillerini orta goýup, täze bir halkyýeti – türk halkyýetini emele getiripdirler.1 Şol döwürler Altaýdan uzak Günbatarda oguzlaryň, kanlylaryň (ganlylaryň), bejeneleriň eýýäm özbaşdak halk hökmünde ýaşap ýörendiklerini saňa ýetirmek, hormatly okyjy, bizi esasy maksadymyza – oguzlaryň türkütlere görä has gadymy halkdygy, asyl-ha şolardan gelip çykmandyklary gaýtam olaryň gözbaşynda durandyklary baradaky söhbedimize golaýlaşdyrýar. Bejeneler, kanlylar kimin käbir kabylalary hem şol döwürde aýratyn halk hökmünde ýaşap ýören bolsalar, onda oguzlaryň özleriniň ―türkütlerden nijembir asyr öň kemala gelendiklerini indi özüňiz göz öňüne getiriberiň. Şeýle bolsa onda orta asyr taryhçysy Mahmyt Kaşgarly tarapyndan orta atylan: ―oguzlar türki kabylalaryň biridir‖ diýen düşünje nireden peýda bolduka? Bu – biziň pikirimizçe şeýleräk bolmaly. Ýagny, täze dörän türki kowum şol döwür dumly-duşa iňňän çalt ýaýrapdyr. Orhon-Ýeniseý türkileriniň gol ýaýradan meýdany Gündogarda demirgazyk Hytaýdan başlap, Günbatarda Wizantiýa çenli, Demirgazykda Manusin çöketliginden başlap Týan-Şan daglaryna çenli baryp ýetipdir. Şol döwürde türkilere goşulan halklaryň ählisine keseki ýurtly syýahatçylar we taryhçylar tarapyndan ―türkiler‖ diýlipdir. Araplar Sogduananyň demirgazygyndan başlap Orta hem Merkezi Aziýanyň ähli çarwalaryny

