INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (39,1,39,'Ýe. Malowa salgylanyp Othon ýazgylarynyň dilini hem oguz dili hasap edýär1. Oguzlaryň hakykatdanam türk hanlygyndan çetde durmandyklaryny Tonýukuk hormatyna ýazylan ýazgydaky: ―Türk Bilge kagan türk syr budunyg oguz budunyg içigi oldur‖ /Türk hany Bilge kagan türk syr halkyny we oguz halkyny beýgeldip otyr/ diýen sözler hem subut edýär. Ýöne şu ýerdäki ―oguz budunyg‖ diýen söze aýratyn üns beriň. Egerde L. N. Gumilewiň aýdyşy ýaly oguz sözi hem ―budun‖ ýaly ―taýpa‖ Manysyny aňladýan bolsa, onda şol iki söz şu ýerde reňkdeş gelýär we ikisem ―taýpa‖, diýen manyny berýär. Netijede bir söz iki gezek gaýtalanýar. Biziň pikirimizçe bu ýerde ―oguz‖ sözi halkyň ady manysynda, ―budun‖ bolsa ―halk‖, ―il‖ Manysynda gelýär. Ýagny, ―oguz halky‖, ―oguz ili‖. Diýmek, türk hanlygynyň içinde türkütler bilen oguz ili hem deň derejede hereket edýär. Türk hany Bilge kagan oguz ilinem türk halky bilen deňderejede görýär. Ikisinem deň beýgledýär. ―Oguz‖ sözüniň ―taýpa‖ manysynda gelýändigi baradaky söhbetiniň soňuny L. N. Gumilew şeýleräk jemleýär: ―Şeýlelikde ―oguz‖ sözi başda ―taýpalar‖ Manyny aňladyp, soň etniki ada öwrülipdir. Soňabaka ―budun‖ sözi kimin o-da öz ähmiýetini ýitiripdir we türkmenleriň legendar nesilbaşysy Oguz hanyň adyna öwrülipdir‖, Iň geň ýerem, oguzlaryň türkilerden uzak günbatarda aýratyn halk hökmünde ýaşap ýörendiklerini hut özüniň salgy berýändigine garamanan L. N. Gumilewiň oguzlaram, Oguz hanam türk hanlygynyň içinden, täzeden howaýy ýerden döretjek bolup ýörmesidir. L. N. Zgumilewiň bu pikirini hormalty alymymyz A. Jykyýew hem goldaýar2. Ol muny gadymy türki çeşmelerde ―oguz‖ sözüniň has at hökmünde duşmaýandygy bilen delillendirýär. ―Oguz‖ sözüniň başda has at bolup, soňam giden bir halkyň adyna öwrülendigini köre hasa edip duran subutnamalary tapmak elbetde kyndyr. Belki-de ol subutnamalar gadymy hytaý ýazgylarynda, Oguz hanyň azm eden

