INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (42,1,42,'rawylary rowaýat edenlerinde aýdan rowaýatlaryny ýurdy edara edijiniň ýada agalyk ediji synpyň talabyna, şol döwrüň syýasatyna görä üýtgedýär. Ýöne, her niçik hem bolsa eseriň başky sudury saklanýar. Bu ýagdaý ýeke bir Oguznamada däl, ―gorkut atada‖, ―Görogluda‖ hem şeýledir. Biziň üçin iň gymmatlysy welin, eseriň başky sudurydyr. Şeýlelikde, ―oguz‖ sözi ―taýpa‖ Manysynam aňlatmaýar, türk hanlygynyň içinde döräp, soň oguz halkyna, ondan soňam Oguz hanyň adyna hem öwrülmeýär. ―Dokuz oguz‖, ―üç oguz‖ sözi bolsa, türk hanlygynyň içindäki oguz taýpalarynyň birleşigini aňladýar. Şeýle aňlatma türk hanl;ygyna giren beýleki halklaryň mysalynda hem gabat gelýär. Mysal çýin: ―otuz tatarlar‖, ―tokuz tatarlar‖. Eýse şu ýerde ―tatar‖ sözem ―taýpa‖ Manysynda gelýärmikä? Ýok! Bu asla beýle däl! ―Otuz tatarlar‖ Hytaý ýazgylarynda ―şiwäý‖ diýlip atlandyrylýar. Bu bolsa gadymy ―sýanbi‖ sözüniň ýoýlan görnüşidir. Sýanbiler bolsa bilşiňiz ýaly halk. Diýmek, ―otuz tatarlar‖ sözi halky aňladýar. ―dokuz oguz‖, ―üç oguz‖ sözüne hem hut şol terzde garamak gerek. / ―Ýedi oguz‖ görnüşinde duşýan ýeri hem bar/ ―Dokuz oguzlaryň‖ hut oguz taýpa bileleşigidigini, onuňam hut türk hanlygyna girendigini akademik W. A. Gordlewskiý hem belläp geçýär. Ol şeýle ýazýar: ―...Oguzy – odna iz tureskiýih/ ―týurkskih‖ bolmaly. J. H./ plemen, o nih upominaet orhonskiýe nadpisi ÝIIIw. Oni delilis na dewýat rodow /‖tokuz-oguz‖/, sifra ―dewýat‖ goworit o bolşoý wnutrenneý znaçimosti etogo plemeni1.‖ Käbir çeşmelerde dokuz oguzlaryň oguz massasyndan aýratyn görünýändiginem olaryň türk sredasyna aýratynlykda we has ykjam aralaşan bolmaklarynyň mümkindigi baradaky pikirimizi tassyklaýar. Mysal üçin, IX a. taryhçy Ibn Hordadbeg türki dilli halklaryň jugrafiki taýdan ýerleşişi barada şeýle ýazýar: ―Страна турок тугуз огузов – самая обширная из тюркских стран. Граничит она с Сином, ат-Туббатом и Карлуками, /затем идут/ ким