INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (43,1,43,'bölege öwrülendiklerine, syýasy taýdandan türkileşendiklerine şaýatlyk edýär. Dokuz oguzlaryň umumy massadan aýratyn görünýän ýeri arap jugrafiýaçysy Ibn-Hawkalýanyň ―al-Guziýa‖ atly eserinde hem göze ilýär. Ol IX-X asyrlarda oguz türkmenleri Mawerrannahryň aňyrsynda, Syr derýanyň aşak akymynda ýaşardylar, olardan gündogar tarapda garlyklar, olardan gündogarda, ýagny, Ýedisuwda (Семиречье) bolsa ―tokuz oguz‖ taýpalary ýaşaýardylar diýip ýazýar. Gepiň gysgasy ―dokuz oguzlar-a uýgurlar däldir, ―Üç oguzlaram‖ garlyklar däldir. Şeýdaýynyň: ―uýgur diýip eşitmiş oguzlary‖ diýen gyjytly setirlerem öňde-soňda şol iki halky taryhyň gatynda garjaşdyrýanlara gahar edilip ýazylan bolsa gerek1. Dokuz oguzlaryň türk hanlygynyň esasy bölegini düzendigi baradaky subutnamany Kültegin hormatyna bagyşlanan kiçi ýazgydan hem getirmek boljak. Şol ýerde Bilge Kagan şeýle diýýär: ―Dokuz oguz begleri, buduny bu sözümi ýagşyja eşidip, üýnümi aňlaň!‖ Kültegin hormatyna bagyşlanan uly ýazgydan mysal: ―Türk oguz begleri budun esidiň!...‖ Ine, orta asyr taryhçysy Mahmyt Kaşgarly tarapyndan orta atylan, ―oguzlar türki kabyladyr‖ diýen ýalňyş düşünjäniň döremegine sebäp bolan ýagdaý megerem şudur. Ýagny, oguzlaryň ―dokuz oguzlar‖, ―üç oguzlar‖ böleginiň türki sreda has golaý durup, has göze ilerlik türkileşenligidir. ―Dokuz oguzlar‖, ―üç oguzlar‖ barada bes! Indi oguzlaryň umumy böleginden habar alalyň. Oguzlaryň galan böleklerem türki dünýäden daşda durandyrlar diýip bolmaz. Ýöne, olar baradaky gürrüňi Günorta Türkmenistanyň ilatynyň baryp-ha miladydan öňki II müňýyllykda, Murgap deltasynyň, Amyderýanyň orta akymlarynyň üsti bilen Günorta Sibire we demirgazyk Hytaýa aşandyklary we II-ÝI asyrlarda yzlaryna dolanyp başlandyklary baradaky pikiriň hem bardygy bilen başlaýsak kem bolmazmyka diýýäris. Bu barada türkmen alymy Ö. A. Ödekow ―Türkmenleriň teke taýpasynyň adynyň döreýşi hakynda‖ atly makalasynda habar berýär?2

1 Şeýdaýy. Aşgabat. ―Ylym‖ 1978 ý. 33 sa. 2 Türkmen halkynyň gelip çykyşy, dünýä ýaýraýyş we onuň döwletiniň taryhynyň problemalary baradaky halkara ylmy konferensiýanyň dokladlarynyň we habarlarynyň tezisler‖ Aşgabat. ―Ruh‖ neşirýaty. 1193 ý. 45 sah. /Mundan buýana bu iş: ―Konferensiýanyň tezisleri‖ diýlip atlandyryljakdyr./

