INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (46,1,46,'Bu, hakykatdanam şeýledir. Ýöne, öküzler, göksüýrililer, änewliler ýaly has irki ýerli taýpalaryň miladydan öňki IV, III,II müňýyllyklarda dürli taraplara – Sibir, Altaý, Mongolystan, Hytaý sebitlerine gidendiklerini miladydan öňki II-III a. bolsa yzlaryna dolanyp başlandyklaryny biz öňde aýtdyk. Şonuň üçinem iki eýýamyň örküjinde şu topraga aralaşyp ugran we ýerli halklar bilen garyşyp başlan türkiler‖ hem, belki bir zamanlar şu toprakdan giden we IX-XI asyrlarda ata-watanlaryny küýsäp, lükgeleýin yzlaryna dolanan öküzleriň-oguzlaryň Türkmenistana aralaşan has irkiräk bölekleridir? Biziň bu pikirimize delil bolup biläýjek mysallar bar. Mysal üçin, türkmen alymy K. Nurmuhammedow asly oguz bolan we türkmen halkynyň kemela gelmeginde görnükli rol oýnan salyrlaryň baryp-ha ÝII asyrda Sarahsda oturandyklary baradaky maglumata arap çeşmelerinde duşmak bolýandygyny habar berýär. Şeýle hem ol VIII asyrda Mary etraplaryna syýahat eden Dinawere salgylanyp, şol ýerde gara guzlaryň we çarwa guzlaryň ýaşandygyny belleýär.1 Onsoňam Eýran dilli, ýerli hasap edilýän halklaryňam esasan şol gadym döwürde şu ýerden giden halklaryň – öküzleriň, göksüýrilileriň, änewlileriň galyndylary bolmagynyň ahmaldygyny-da unutmalyň. Muny şol halklaryň taryha taýpa atlary bilen däl-de, öz oturan ýer-ýurt atlary bilen ýagny, margianalylar, horasanlylar, kaňlylar diýen ýaly atlar bilen girendikleri hem tassyklaýar. Bu meselede alymlary biziň şu pikirimize garşy goýjak zat – şondan soň, ýagny, iki asyryň örküjinde bu topraga ―türki‖ halklar aralaşyp başlandan soň, ýerli halkyň kelleçanagynyň ýasylaşyp başlandygy baradaky habarlardyr. Olar munuň üçin öňi bilen Al-Masudynyň: ―...oни /огузы ж.х./ самые храбрые из тюрок, самые маленькие из них ростом и у них самые маленькие глаза‖ diýen sözlerini tutaryk edinýärler. Ýöne, ylym üçin irki alymlaryň ýazyp giden zatlarynyň ählisini gutarnykly tutaryk edinmek dogry däldir. Çünki, birinjiden-ä Al-Masudynyň göreni oguzlaryň ―üç oguzlar‖, ―dokuz oguzlar‖ ýaly, türki sreda has golaý durup, haýsydyr bir mongoloidleşen, ýa-da oguzlara goşulyp, oguz adyny alan genetiki däl-de syýasy taýdan türkileşen mongolsypatly türkiler bolmagy mümkin. Ikinjidenem, orta asyr taryhçylary gözi bilen gören, gulagy bilen eşiden 1 K. Nurmhammedow. ―Salyr etnosynyň türkmen iliniň döreýşinde tutýan orny‖ /Sarahsyň 2500 ýyllygyna bagyşlanyp geçirilen ylmy maslahatyň çykyşlaryň gysgaça mazmuny. Aşgabat. 199 2 ý. 7sah./

