INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (48,1,48,'Diýmek, ýerli halklaryň türki‖ halklar bilen garyşyp, türkmen halkynyň kemala geliş prosesiniň ilkinji etaparyny başdan geçiren döwründe, oguzlar bu uly ―gurluşdan‖ hem çetde durmandyrlar diýmäge-de olary gelmişek ýa-da mongolid saýmazlyga esas ýok däl. Şu ýerde biziň mongol, gypjak sähralyklarynda, Aral töwereklerinde, Ýedisuwda, Türküstanda, Altaýda, Sibirde, Hytaýda, häzirki Gazagystanyň, Özbegistanyň çäginlerde oturan dürli-dürli türki halklaryň hem, sergezdançylykda geçiren müňýyllyklarynyň dowamynda öküzlerdenoguzlardan sypyrylyp galan aýry-aýry şahalar bolaýmagynyň mümkindigi baradaky çaklamany hem orta atasymyz gelýär. Sözümizi delillendirmek üçin gazaklaryň, özbekleriň, garagalpaklaryň, başgurtlaryň birwagtlar gypjak soýuzyna girendiklerini, gypjaklaryň bolsa has irki bejenelerdigini mysal getirip bileris. Bejeneler /печенеглер/ bolsa, bilşiňiz ýaly oguz kabylasydyr. Gyrgyzlaryň oguz hasap edilýändigini bolsa inkär edýän ýok. Mysal üçin, Ata Jykyýew gyrgyzlaryň Altaýda türkmenler bilen goňşy ýaşan döwürlerine degişli ýygnan rowaýatlaryna salgylanyp şeýle ýazýar: ―Gyrgyzlar birmahallar Altaýda ýaşapdyrlar. Şol wagt olaryň hany Kirgizkan ekeni. Nesilbaşylaryna bolsa, Uguzkan diýer ekenler‖. Şu ýerde Kirgizkanyň – Gyrgyz han, Uguzkanyň – Oguz handygy öz-özünden düşnükli bolsa gerek. Ýöne, gyrgyzlar mongol sredasyna düşüp, mongolidleşen oguzlardyr. Umuman, türkmen halkynyň kemala gelmeginde oguzlaryň esasy rol oýnandyklary jedelsizdir. Olaryň hunlardanam, gunlardanam, türkütlerdenem, gök türkilerdenem has irki halkdygy, kem-käs garylypgatyşmaklygy nazara almanymyzda, agzalan halklaryň olara genetiki taýdan hiç hili dahyllarynyň ýokdugy, ―türk‖ adynyňam türk hanlygy döwründe syýasy taýdan däl-de edil ―oguz‖ sözi ýaly, turubaşdan boýunlaryna dakylandygy, özleriniňem asyl-ha mongoloid däl-de, öň ýewropoid bolandyklary, şu toprakdan tapylýan süýri kelleçanaklarynyňam hut şolaryň ata-babalary bolan öküzlere degişlidigi, ýerli halk hasap edilýän parfiýalylaryň, margianalylaryň, dahlaryň, massagetleriň hem asmandan düşen däl-de hut şolardan bölünip galan halklardygy, özleriniňem asyl-ha eýran dilli däl-de, gadymy oguz dilli halklar bolandygy gaty ähtimaldyr. Ýöne, olaryň belli bir döwürde syýasy sebäplere görä, Eýran dilini döwlet dili hökmünde kabul eden bolmaklary ýa şol dilde gürlän bolmaklary mümkin.

