INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (52,1,52,'bärki ujy bilen tapyşyp äpet halkany – ellipsi emele getirýär. Ol halka dik ösüp oturan ýerli türkmen liniýasyna iki gat towlam görnüşinde çyrmaşýar. Şondan soň bu iki liniýa äpet uly sütüne öwrülýär. Bir zamanlar ady-abraýy äleme dolan, Oguz han dek ärleriň öňünde gylyç geren, Beýik Hytaý diwarlarynyň eteklerinde gyşlap, mongol sähralyklarynda ýazlan, Talasdyr Selenganyň seleň sähralyklarynda gyz söýüp, Toli derýasynda inini päklän, Syr suwunyň aşak akymlarynda goýun kökerip, Aral degrelerinde at segreden, Amy derýanyň üsti bilen agras, mähnet bir tolkun dek türkmen topragyna - gadymy mekanyna, atawatanyna aralaşan oguz ili ine, şeýdip, edil Garagumyň ürgün çägelerine siňen dek, ýap-ýaňyja türkmen adyny alan gadymky Watandaşlarynyň – türkmen halkynyň süňňüne siňýär. Emma olar gadymy türkiler ýaly ýerli halkyň boýnuna öz atlaryny dakyp bilmändirler. Gaýtam görlüp-eşidilmedik çaltlykda özleri türkmenleşip başlapdyrlar.‖Türkmen‖ adyny alypdyrlar. Daňdanakanyň ýanynda Soltan Mesgudyň garşysyna bolan söweşi beýan edýän taryhçylaram eýýäm ―türkmen‖ sözüni ―oguz‖ sözünden ileri tutup ýazýarlar. Soltan Mesgudy agdaran oguzlaryň doly türkmenleşendiklerini Baýhakanyň indiki setirlerindenem aňmak bolýar. ―...Masudyň tertip-düzgüni oňly bilmeýän goşunlary çym-pytrak boldular. Soltanyň lagerini taşladylar, netijede olaryň ähli baýlyklary türkmenlere galdy‖. Baýhaky 1040-njy ýylda, Daňdanakan söweşi bolmanan öňem Horasanyň Merw, Nusaý, Sarahs, Ferawa ýaly uly şäherleriniň türkmenleriň garamagynda bolandygyny aýdýar. Ýu. Ýakubowskiý hem özüniň: ―XI asyrda Seljuklar hereketi we türkmenler‖ atly işinde, taryhçy Baýhakanyň şu sözlerini getirýär: 1035-nji ýylda türkmenler – seljuklar gönendiler. Dehistandan başlap tä, Nusaýa çenli bolan aralyk olaryň eline geçdi. 1037-nji ýylyň başynda türkmenleriň ―gyzyl‖ hem-de ―ýagmyr‖ tireleriniň we balhankuhlaryň ýerli, syýasy işlere gatyşyp, döwlet 