INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (55,1,55,'Türkmenleriň hiç haçanam edil, agyz dolduryp aýdar ýaly mongoloidleşmändigini biz ýokarda-da ýaňzytdyk.. bu bolsa öňi bilen oguzlaryň – öküzleriň ýewropid halk bolandyklary bilen baglydyr. Asly oguz bolan türkmen, türk, azerbaýjan, gagauz halklarynyň öňde-soňda ýewropoid jynsa degişli bolandyklaryny taryhyň gatynda, has beterem türk hanlygy döwründe oguzlary çalajada saýgarmaýan L.N. Gumilew hem belläp geçýär. Ol bu barada şeýle ýazýar: ―...Şeýlelikde hiç haçan türk hanlygyna girmedik halklaram ―türk‖ adyny aldylar. Mysal üçin: türkmenler, osmanlylar, azerbaýjanlar. Olar hatda mongolid hem däldiler.‖1 Biziň üçin bu sitatanyň iň gymmatly ýeri soňky jümledir. Çünki, alym bu ýerde şol üç halka derek – ―oguzlar‖ diýmekden erjellik bilen boýun gaçyrýan hem bolsa, baryp-ha VI– VIII asyrlar barada gürrüň edýär. Olaryň şol döwür mongoloid halk bolmandyklaryny tassyklaýar. Diýmek, XIV –XVI asyrlarda, şu toprakda täze bir halkyýeti emele getiren türkmen taýpalarynyň içinde süýrükellelileriň ýagny, ýewripoid jynsly türkmenleriň köpelip ugramagy käbir türkmen taýpalarynyň aslyny dahlardan, massagetlerden alyp gaýdanlygy ýa türkmen teninden oguz we gadymy türki geneologiýanyň öz-özünden sykylyp aýrylandygy sebäpli dälde, öňde belläp geçişimiz ýaly, ata-watanlaryna dolanyp gelen oguzlaryň /öküzleriň-turlary[-txrkileri[/ ýüz keşpleriniň we kelleçanaklarynyň şol bir wagtky, entek bu topragy terk edip gitmedik döwürlerindäki keşbini ýitirmän alyp gelendikleri sebäplidir. Özleri lükgeleýin (XIV–XVI aa.) gelmezden öň ýerli halklaryň endamyna kem-käs siňdirilen mongoloid keşbi türkmenleriň teninden sykyp aýyranam hut şolardyr. Galyberse-de, bu prosesde goňşy Eýran, Owgan halklarynyň, arap dikmeleriniň galyndylarynyň, alamançylyk belasynyň esli wagtlap kiçi Aziýasy, Ermenistan, Gürjüstan, Azerbaýjan ýurtlary bilen bolan aragatnaşyklaryň görnükli rol oýnandygyny hem ret edip bolmaz. Azerbaýjan, Gürjüstan, Ermenistan ýaly ýurtlardan gyz almak däbi hatda türkmen dessanlarynyň baş temasyna öwrülipdir. Bezirgenlik täjirlik

1 L.N.Gumilew. ―Дp.т.‖/ L.N.Gumilew. şu işinde has irki zamanlarda Gündogar Aziýada diňlinler we Diler atly iki sany ýewropoid halklaryň ýaşandygyny habar berýär. Diler Hytaý serhetlerinde diňlinler bolsa Sibirde ýaşapdrlar. Olar ýewropoid, hatda ―aksowult saçly‖ bolupdyrlar. Hytaýlylar dileri hem Diňlinlerdir öýdüpdirler. Şeýle hem olar Saýan daglaryna ―Diňlin daglary‖ diýer ekenler. Dileriň b.e.ö. VII a. Hytaý tekizligine çozup girendiklerini, b.e.ö. II a. Başlap Hytaýlylaryň olary Merkezi Aziýanyň birnäçe halklarynyň ata-babalary diýip tanandyklaryny Täjigistanly alym I. W.Pýankow hem özüniň ―Skif-Sibir medeni umumylygyna taryhy jähtden garaýyş‖ atly makalasynda ýazýar. ―Konferensiýanyň tezisleri‖ 37 sah Ýöne onuň Dileri mongoloid hasap edýär. ―Aksowult saçly diňlinleriň bolsa asla bolandyklaryna-da ynanmaýar. Bu elbetde, onuň öz işi. Ýöne, biziň pikirimizçe şl döwürde, şol etraplarda ýaşa ―Di‖ hem-de ―Ýuäçji‖ taýpalarynyň birleşip, türkmeniň meşhur ―Düýeji‖ taýpasyny emele getiren bolaýmagynyň ahmaldygy barada hem oýlanylyp görüläýse kem bolmazmyka diýýäs.

