INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (64,1,64,'18. SSSR-iň dargamagy. 18. Türkmenistan bilen /1991 ý./ Türkmenistan özbaşdak gatnaşygyň ýola goýulmagy. halda. Türkiýe bilen gatnaşygyň açylmagy.

