INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (65,1,65,'―türkmen‖ adyny has irkiräk döwürlerde hem bile tutmagymyz we çykgynsyz güne düşmegimiz mümkin. Irki eýýamlar bilen biziň aramyzda nijembir möwrütler, nijembir öwrülşikler, garyşyp-gatyşmalar ýatandyr. Nijembir ýitip gitmrklik we täzeden döremeklik bolup geçendir. Göwrämize telim ýola gol bitip, te lim ýola-da ýitendir. Özümize dahylly halklaryň iň gadymylaryny hasaba alyp, aralykdakylary görmezlige salsak, gatbar-gatbar bolup duran tenimizdäki käbir gatlaklaryň göwnüne degdigimiz bolar. Türkmenistanyň gadymy halky süýri kelleli bolupdyr diýip türkmenleriň aslyny gös-göni parfiýalylara, margianalylara, girkanlara, dahlara, massagetlere, aslara, alanlara degişli edýän alymlar, şu agzalan halkyýetlerden öň şu çäkde öküzleriň, arileriň soň mesopotamiýa girip şumerlere öwrülen änewlileriň, göksüýrilileriň ýaşandyklary, olaryň käbir bölekleriniň hususan-da öküzleriň soň gaýdyp gelendikleri, käbirleriniň bolsa asylha gitmändikleri süýrikellelileriň hem hut şolar bolaýmagynyň mümkindigi barada hiç bolmanda indiden soň bir köpräk oýlanaýsalar kem bolmany. Hususan-da ―öküzler, turlar‖ barada. Ýokarky shemadaky oguz liniýasyna daş asyrynyň eýkumenlerini, arileri, şumerleri, göksüýrilileri, hapyzlylary bijebaşy edip goşmagymyz hem, özümiziň şu pikirimize garşy gidýändigimiz üçin ýa-da şol gadymy halklary türkmenleriň gös-göni ata-babalary saýmak isleýändigimiz üçin däl-de, irki möwrütlerde, hersiniň hut şol wagtky ýaşan ýerine hakykatdanam şol halklaryň ganyndan öz ganymyza garyndaşlyk ganynyň geçendigine ynanýandygymyz, islendik halkyň taryhyny möwrütlere bölüp öwrenmek prinsipine uýýandygymyz üçindir. Biziň üçin gymmatly ýeri şu toprakdan örňän halklaryň bir ýerlere baryp ―arilere‖, ―sumerlere‖ ýa-da düýbünden başga-başga halkyýetlere öwrülendikleri däl-de, şol halklaryň hemmesiniň büs-bütin göçüp gitmändigi, gitmän galanlarynyň ganyndan ganymyza gan geçendigidir. Biz şol agzalan