INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (66,1,66,'Nemesleriňem, hindileriňem, eýranlylaryňam, owganlylaryňam, Çiwilihine gulak assaň ruslaryňam arilere degişlidigi göz-görtele görnüp durka ―diňe men aridirin‖ diýip gygyryp durmaklygyň gelşiksizdigi özözünden düşnükli bolsa gerek. Şumerler barada hem şeýle. Gadymy ari, şumer, hindi, nemes, eýran, arap, iňlis, rus, ermeni, gürji we käbir amerikan indeýleriniň, köp sanly sibir halklarynyň dillerinde türki sözleriň duş gelmegi, onuňam hut türkmen diline golaý bolmagy olaryň hemmesiniň aslynyň türkmendigi üçin däl-de gadymyýetde türkmenleriňem köp halklar bilen bilelikde köp-köp gadymy halklara dahylly bolandyklary üçindir. Asyl-ha külli adamzadyň aslynyň henize bu güne çenli hiç kime mälim bolmadyk haýsydyr bir gadymy halka degişlidigi, haýsydyr bir öwrümde barymyzyň atamyzyňam, enemiziňem birdigi, birwagtlar hemmämiziňem bir dilde sözländigimiz, bir gowakda ýaşandygymyz bir ojagyň başyndan örňändigimiz üçindir. Eýsemde bolsa nämüçindir şu günki halklaryň köpüsi öz aslyny arilere ýa –da şumerlere dahylly etjek bolup dyrjaşýarkalar? Ýa şolara dahylly bolmak derejemikä? Ýa bu zatlar olaryň gadymylygyny bütin dünýäde ykrar edilendigi üçin şeýlemikä? Ýa ―ari‖ sözüniň ―arassa‖ diýen Manyny aňladýandygy, gadymy şumer sungadynyň şu günki günem bütin dünýäni aňk edýändigi, olaryň baryp-ha birmahallar güýçli döwlet gurup bilendikleri üçinmikä? Biziň pikirimizçe bu ýerde-de aslyňa ymtylmak duýgusy öz hökmüni ýöredýän bolsa gerek. Asly bir adamzat özi-de duýmanan öz gözbaşyna serpilmek duýgusy bilen joşýan bolmaly. Ýöne, bu ýerde aşa sabyrlylyk, sypaýylyk we agraslyk zerur. Ýagny, her kim öz taryhyny öwrenende, beýan edende, halkynyň gelip çykyşyny yzarlanda, syýasy öwrülşiklere ser salanda, seljerende edende, nebsi ejizlikden, badyhowalykdan we gabanjaňlykdan daşda durmalydyr. Has takygy her kim öz taryhyny umumyadamzat taryhyndan fonundan üzňe göz öňüne getirmeli däldir we öz hakyna