INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (69,1,69,'Gepiň gerdişine görä, geliň, ýokarky ady agzalan alymlaryň sergin pikirleri bilen tanşyp göreliň. Mysal üçin, Ödek Ödekow, türkmeniň teke taýpasy öz adyny dag goçundan, ýagny, tekeden alandyr diýip çaklaýar we öz pikirini gadymy ―tukýu‖ sözüniň ―türküt‖ diýip däl-de, teke, ―gök türk‖ sözüniň bolsa ―gök teke‖ diýip terjime edilmelidigi bilen hem-de goç buýnuz şekilini bezeg hökmünde ulanmaklygyň türkmen taýpalarynda ýörgünli bolandygy bilen düşündirýär.1 Gönümel bolmasa-da, onuňky bilen çalymdaş pikiri Moskwaly alym G.P.Wasilýewa hem aýdýar. Ol şeýle diýýär: ―...Geçirilen barlaglar, şeýle-de biziň etnografiki maglumatlarymyz Köpetdagyň demirgazyk eňňitlerindäki käbir uly bolmadyk taýpalary – änewlileri, mürçelileri, nohurlylary oguzlara çenli ýaşan türki taýpalaryň nesilleri diýip hasap etmäge mümkinçilik berýär. Olaryň ählisinde türkmen taýpalaryna mahsus bolmadyk birnäçe özboluşly häsiýetler bolupdyr: meselem, olar haly dokamandyrlar‖.2 Elbetde, bu ýerde jedelleşere zat kän. Iň bärkisi Sumbarda mundan 3,5 müň ýyl ozal haly dokalandygyny N. Gulla biziň şu makalamyzyň golýazmasyny okan döwründe habar berdi. Şeýle maglumatlaryň başga-da kändigine ynanýarys. Ýöne, gaty daşlaşMankak, Ödek Ödekowyň teke türkmenleri baradaky pikirine dolanyp geleliň. Bu ýerde-de öňi bilen bir zady aýdyňlaşdyrmak gerek. Ýagny, eger-de teke türkmenleriniň aslyny öňki ýaly dah-massaget taýpalaryna degişli etsek, onda olary hakykatdanam ýewropoid keşpli süýrikellelileriň hataryna goşmaly bolýarys we mongoloid keşplidikleri şübhesiz bolan türkütlere ýa türkilere degişli etmäge, G. P. Wasilewanyň, Ödek Ödekowyň arkasynda durmaga bizde hiç hili tutaryk galmaýar. Bu antropologiýanyň kadalaryna ters gelýär. Eger-de gadymy türkütlere ýa-da türkilere degişli etsek, onda olar göz-görtele mongoloid bolýarlar we köp alymlaryň şu çaka çenli hut antropologik barlaglara esaslanyp olary dahlara, massagetlere de