INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (70,1,70,'galan şahalary bolmaly. Çünki, öküzler – oguzlar hiç haçanam şu toprakdan aralaryny bütinleý üzmändirler. Talas, Saýram, Altaý ülkelerinde, Aral degrelerinde, Hytaý serhetlerinde, Sibirde, Mongolystan sähralyklarynda bolmak bilen olar Rum, Şam Frank, Müsür ýurtlaryna tarap o ýan, bu ýan birsyhly ylgar edipdirler we atlarynyň altyn nally toýnaklary bilen şu topragy birsyhly ýumşadyp durupdyrlar. Özlerinden soň şu topraga gelip geçen we şu ýerde asyrlarboýy ýaşan ýerli halklaryň goşluşyp garyşyp etniki tarapdan kemala gelmeklerine birsyhly goşant goşup durupdyrlar. Olar gelenlerinde-de ýat ýere däl-de, Ata-Watanlaryny küýsäp, watandaşlaryny, babadaşlaryny gözläp gelipdirler. Bir taýpanyň başga bir taýpanyň içine siňmegi, ýa başga bir taýpanyň içinden dömüp çykmagy ýaly hadsalar bolsa islendik halkyň etnografiki taryhynda, şol sanda oguz-türkmen halkynyň taryhynda-da barmak basyp sanardan kän. Teke türkmenleriniň nesil Şejerelerini hem hut şu nukdaý nazardan yzarlamaga ýol salgy berýän çeşmeler ýok däl. Mysal üçin Abyl Gazy özüniň agzalan işinde teke, saryk, ärsary taýpalarynyň, hyzyr, burkaz iliniň Balkan /Abulhan/ daglarynda oturylýan döwri salyrlardan bölünip çykandygyny aýdýar. Bu pikiri türk alymy Faruk Sumer hem özüniň meşhur ―Oguzlar – Türkmenler‖ atly işinde tassyklaýar. Türkmen alymy Ç. Ýazlyýew tekeleriň uly toparynyň baryp-ha seljuk basybalyşyklaryna gatnaşandyklaryny we Horezm, Sarahs etraplaryndan Kiçi Aziýa göçüp gidip Anadoly welaýatynda mekan tutandyklaryny, şol ýerde ―teke ili‖ begligini döredendiklerini habar berýär. Ol Türkiýeli we Orsyýetli türkmenşynaslaryň pikirlerine salgylanyp, XV asyryň ortalaryndan başlap tekeleriň ―ýörükleriň― (ýörükler ýöregirler – gadymy oguz taýpalarynyň biri) düzümine goşulandyklaryny, olaryň düzüminde häzirem tekeli, gara tekeli, sary tekeli, syçmaz, bagşy ýaly tire bölümleriniň bardygyny belleýär. Şeýle hem ol tekeleriň bir 