INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (71,1,71,'türkmen emirleri, teke aşireti, teke begleri, teke ili, teke kowumy, igdir, karaman we ş.m. maglumatlara häli-şindi duşýarsyň‖ diýip ýazýar.1 Şeýle hem ol 1879-njy ýylyň 2-nji ýanwarynda iňlis Korollygynyň jugrafiýa jemgyýetiniň mejlisinde Roulinsonyň eden dokladyna salgylanyp, III asyryň soňlarynda ýuçjiler tarapyndan Amyderýanyň aňyrsyndan bärik, Hazar deňziniň kenarlaryna tarap gysylan we soň-soňlar Nusaý bilen Dehistan aralygynda ýaşan ―dage‖ /hytaýça tagiýa-tahua/ taýpasynyň adyny belli bir netijä gelmese-de, häzirki teke türkmenleriniň ady bilen ýüzugra degşirip geçýär.2 Şol ―dage‖ taýpasynyň dahlardyr ýa däldigini çözmek, elbetde, ylmyň işi, ýöne, şolar ―dahlar‖ bolup, teke türkmenleri hut şolardan gelip çykan bolaýanlygynda-da, geliş ugurlaryny yzarlasaň, yz oguzlaryň gadymy mekanlaryna tarap alyp barýar. Şujagaz mysallaryň özem teke türkmenleriniň gadymy oguz taýpalaryna degişli edilmelidigi baradaky pikirimize goltgy berýär. A. Roslýakow ýaly käbir alymlaryň ýomut türkmenlerini sarmatlara degişli etjek bolmaklary hem iňňän jedelli meseledir. Bu barada biz Çary Ýazlyýewiň agzalan makalasynda düýbünden başgaça maglumatlara duş geýäris. Ol Hytaý goşuny üçin düzülen, ―garaşly hanlyklaryň tagmalary‖ diýen sanawda ýomut atlarynyň VII–VIII asyrlarda Merkezi Aziýada iň gowy atlar hökmxnde görkezilendigini belleýär. Alymyň aýmagyna görä, şol sanawda ýomut etnonimi ―ýuýý-mäý-hun‖ görnüşinde ýazylyp, hunlaryň ýomut tiresi diýen Manyny aňladypdyr. Elbetde, muňa gutarnykly pikir hökmünde garap bolmaz. Ata Jykyýewiň Salyr Gazan barada ýomutlaryň arasyndan ýazyp alan rowaýatynda salyrlaryň, saryklaryň, ärsarylaryň, tekeleriň, ýomutlaryň ganybir garyndaşdyklary, dogandyklary nygtalýar.3 Bu bolsa ýomut türkmenleriniňem gelip çykyşlary boýunça oguz türkmenleriniň hatayna goşmaklyga mümkinçilik döredýär.

