INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (72,1,72,'Dogry, bu rowaýat ýokarky agzalan taýpalary özüne birikdirip, iki asyr dowam eden XIV-XVI salyr taýpalar bileleşiginiň täsiri bilen ýüze çykan bolmagam mümkin, ýöne, her niçik hem bolsa suw hem öň akan ýerine tarap akarmyş. Halklar, taýpalar, uçuglar hem hemişe garyndaşlyk ganyny yzarlaşmak arkaly birleşýärler. Biz salyr taýpalar birligem tötänden ýa diňe syýasy bähbitler arkaly däl-de, doganlyk küýsegi arkaly dörändir diýip pikir edýäris. Her hal Ö.Ödekow, Ç. Ýazlyýew ýaly henize-bu güne çenli türkmen etnografiýa ylmynda aýdylmadyk batyrgaý pikirleri orta atmaklarynyň özi-de uly ädimdir. Guwançly we gutlamaly zatdyr. Tekeler, ýomutlar ýaly şu günki gün öňe çykan we san taýdan iň köp bolan türkmen taýpalarynyň şu çaka çenli gelip çykyşy boýunça beýleki taýpalardan aýry edilip görkeziljek bolşy, hiç kimiň günäsini götermäýin welin, megerem, türkmen halkynyň agzyny alardyp, agaýana höküm sürmek üçin, olary ruhy we şejere taýdan golaýlaşdyrmazlyk we birleşdirmezlik üçin, kolonial düzgüniň we ondan soňky sisteManyň syýasatlaşdyrylan ylmy tarapyndan oýlanyň tapylan zat bolsa gerek. Umuman sözümizi jemläp aýtsak, oguz liniýasy türkmen liniýasy bilen, türkmen liniýasy oguz liniýasy bilen tapyşýança örän uzak we çylşyrymly ýol geçdi. Şonuň üçinem, jylawyň ujuny gutarnykly ele almak juda kyndyr. Belki, mümkinem däldir. Türkmeniň ýeke bir teni däl, tutuş taryham gat-gatdyr. Bir gatyna el ýetirdim diýseň, aňyrda ýene bir gatlak garalyp ýatandyr. Ol gatlagam dürli şahalardan, şahalar ýapraklardan, ýapraklar inçejik damarlardan ybaratdyr. Şol inçejik damarlaryň syzýan nemleri bolsa, dürli kökleriň içinden geçip gelýändir. Şol köklerem öz gezeginde ýene sansyz-sajaksyz gotazjyklara, çylgymlara bölünýändir. Asyrlaryň jümmüşine, taryhyň çuňluklaryna aralaşdygyňsaýy halklar biribirine golaýlaşýandyr. Haýsy halkyň gelip çykyşyny yzarlasaňam, onuň geneologiýasyndan başga bir halkyň gatanjy