INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (74,1,74,'Ata, Ene welin nirede bolsa-da – Atadyr, Enedir: Watan – nirede bolsa-da Watandyr! Ol ikisini bölmegem, bölüşmegem nädogrudyr. Aslyýetinde biziň barymyzyň Watanymyz asman giňişliginiň içinde ýüzüp ýören ýalňyz gämi – goja zemindir: Öýümiz gök asmanyň astydyr! Tylla tas tugumyz, mele toprak mesgenimizdir. Atamyz – Adam ata, enemiz – How enedir. Şolar bilen aralykda bolsa, çal dumana duwlanyp agyr heňňam aňyrsyna göz ýetirmesi kyn bolan çylşyrymly gözlegler, sargylt syrlar ýatandyr. Biziň borjumyz ana, şol gözlegler arkaly aňymyz bilen mümkingadar kökümize, birek-birege golaýlaşmakdyr. Bu zemin üzre biz nirä göçsek-de, nirede gonsak-da hiç birimiziňem şu togalak şardan düşüp gitjek ýerimiz ýok.

«Ýaşlyk»–«Юность»žurnaly, 1993., niýabr; 1994., fewral.

