INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (80,1,80,'Her-hal biz onuň Teke han ýagny, Tekemuhammet adynyň hakykatdanam dogabitdi adydygyna ynanýarys. Bir adyň yzyna Muhammet sözüni goşmak bolsa, umumanam Teke hanyň Şejeresine mahsus bolupdyr. Ýagny, kakasynyň ady Nazarmuhammet. Öz ady – Ýazmuhammet. Ogullarynyňam briniň ady – Muhammet /Mämmet/ Teke hanyň atasy Gutly hanyň, babasy Berdi hanyňam atlarynyň Gutlymuhammet, Berdimuhammet görnüşinde bolandygyny aýdýarlar. Ýöne, nämüçin onuň bir adyna Ýazmuhammet goýdularka? Bu onuň ýaz aýy doglandygynyň alamaty bolmagy mümkin. Ýöne, salyrlarda öwliýä ―nyýaz‖ aýdylyp alynýan çaganyň adynyň öňüne ―nyýaz‖ däl-de, ―ýaz‖ goşulmasyny goşmak edähedi hem bar. Teke hanyňam öwlýä ―nyýaz‖ aýdylyp alnan çaga bolmagy mümkin. Çünki, Şamman aganyň aýtmagna görä ol Nazar hanyň çagalarynyň iň ulusy bolmaly. Ýöne, barybir ol şejerede ýeke görünýär. Çünki has ir ýogalan bolsa gerek, Ärsary barada Şamman aga hiç zat aýtmady. Haknazaryň ykbaly bilen bolsa, makalamyzyň dowamynda tanşyp bilersiňiz.

