INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (83,1,83,'Şeýlelikde, salyrlaryň Maryda, Pendide oturan döwürleri Teke han Gowşut han tarapyndan han saýlanybam bilýär, onuň bilen deňli-derejeli adam hökmünde gatnaşybam bilýär. Şol wagtlar ol takmynan, 40-45 ýaşlaryndaky adam bolmaly. Seýit aganyň gep salgysyndan çen tutanymyza görä, Teke hanyň ýaşy iküç ýaş eýläk ýa beýläk bolup biler. Iň bärkisi taryhçylar Meňli hanyň 1919njy ýylda däl-de, 1918-nji ýylda öldürilendigini tassyklaýarlar. Çünki, 1918nji ýylda eýýäm Eziz hana aklar tarapyndan sud edilip ýördi. Seýit aga Teke hanyň şejeresini şeýleräk beýan edipdir. Aňyrlygyna – Teke han – Nazar han – Gutly han – Berdi han. Bäriligine – Teke han – ogullary: Şajyk, Mämmet /Myhammet/. Gyzlary: Täç, Sona. Şajykdan: ogullary – Juma, Şamman, Gumman. Gyzlary: Ollan, Aman, Sähra, Gurbangül. Mämmetden üç gyz bolup, üçüsiniňem ýogalandygy aýdylýar. Ýöne, Seýit aganyň görkezýän şejeresinde Mämmediň Aýjemal, Gylyçdurdy atly gyzlarynyň hem ady bar. Teke hanyň Täç atly gyzyndan hiç zat ýok. Sona Eýrana giden. Göçhä-göçlük döwri adamsy gidýär, o-da gidýär. Şular ýaly şerejäni Şamman aganyň agtyklarynyň arasynda-da ýöredýäni bar. Olaryňkam umuman, Seýit aganyňky bilen gabat gelýär. Şamman aganyň aýdyşy boýunça Teke han üç aýal alypdyr. Ýagmyr Ýazberdi şolaryň biriniň adynyň Hurma, başga biriniň Annagül, ýene biriniň Ogulgurban bolandygyny, şeýle hem Teke hanyň Şajyk oglunyň birinji aýalyndan, Mämmet oglunyň ikinji aýalyndan bolandygyny, ýagny, Şajyk bilen Mämmediň enebaşgadygyny habar berdi. Nobat aga kakasynyň, ýagny, Mämmediň Annagülden bolandygyny tassyklaýar. Şeýlelikde, Ýagmyr Ýazberdiniň salgysyndan çen tutsak Annagül Teke hanyň ikinji aýaly, Hurma birinjisi bolup çykýar. Şunuň dogry bolmagy mümkin. Çünki, Annagül kör eken. Teke han ony birinji aýaly ýogalandan soň, önelge üçin alan ekeni. Ikinji aýalam ýogalandan soň Teke han Ogulgurbana öýlenýär. Ogulgurbandan önelge ýok. Täç bilen Sonany