INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (86,1,86,'Bar, ol entek ýaş eken, dünýede bar eken, hanlygam tabşyrman eken diýäýenimizde-de, Romanowlaryň tagt toýuna Sarahs ýaly kiçi pristawlaryňk-a beýle-de dursun, hatda uezd hanlyklarynyňam hemmesi çagyrylan däl bolsa gerek. Ol ýere Zakaspi oblastynyň diňe Aşgabat, Mary, Kerki ýaly uly hanlyklarynyň hanlary giden bolmaly. Sarahsdan han gitmeli bolaýanda-da, ol gezek Teke han däl-de, Meňli han gitmeli. Çünki Teke han hanlygyny baryp-ha geçen asyryň aýagynda şoňa tabşyrypdy. Ikinjidenem, henize çenli Gylyç Penjuwardan başga şol suratdaka Teke han diýen adam ýok. Hatda şol surat öňürti Magtymguly hanyň, soň Ýusup hanyň ady bilen žurnalda çap bolandan soňam şu suratdakylary tanaýan adam bar bolsa seslensin, diýip redaksiýa uly ile jar çekenden soňam şol suratyň Teke hanyňkydygyny tassyklap, ne sarahslylardan, ne-de taryhçy alymlardan seslenenei bolmady. Üçünjidenem ol döwür Teke han segsenden geçen adam. Suratdaky bolsa ýaş. Onda uzak ýaşan adamyň ak sakgal-a baýaky, iň bärkisi sarahslylaryň aňyna uzyn boýly, gara çäkmenli Teke hanyň ýeke-täk nyşany hökmünde giren uzyn gara sakgalam-a ýok. Onsoňam suratdakynyň Ýusup handygyny, şondan başga adam däldigini ähli arhiw dokumentleri tassyklap dur. Muny akademik M. Annanepesowam, türkmen hanlary barada ylmy iş ýazan Muhammetgurban Orazow hem, beýleki alymlaram çürt-kesik tassyklaýarlar. Iň ýeser ýeri Ýusup hanyň özi ýüzüňe seredip otyr. Mahlasy, belli zat barada jedel edip oturmagyň geregi ýok. Elbetde, suratda 1913-nji ýylda türkmeniň iň uly taýpalarynyň hany hökmünde Peterburga, toý dabarasyna çagyrylan uly hanlar: Magtymguly han, Ýusup han, Güljemal han dagy otyrlar. Has takygy Güljemal han öz ogullary bilen otyr. Indi jedlli meseleleri bir tarapa süýşürip Teke hanyň bitiren hyzmatlaryna, taryhy hereketlerine we on dokuzynjy asyryň birinji ýarymyndan başlap tä, segseninji ýyllaryň ortalaryna çenli iň bir pajygaly wakalary başyndan 