INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (94,1,94,'Biziň pikirimizçe Kemine-de, Mollanepesem Sarahsa şol, Oraz Ýaglynyň getiren teke türkmenleri bilen gelen bolmaly. Sarahsa gelenlerinde Mollanepes 26 ýaşynda, Kemine şahyr bolsa 66 ýaşlarynda bolmaly. Muny bilmek üçin şeýleräk hasap ýöretmeli: Mollanepesiň doglan ýyly 1810-njy ýyl, Sarahsa gelen ýyly 1836-njy ýyl. 1836-1810=26. Keminäniň doglan ýyly 1770-nji ýyl. Diýmk ol Sarahsa ömrüniň iň soňky ýyllary gelipdir we ol ýerde bary-ýogy dört ýyl ýaşap ýogalypdyr. Okuw kitaplarynda Keminäniňem, Mollanepesiňem doglan ýeri Sarahs diýlip şu çaka çenli nädogry görkezilip gelinýär. A. Gürgeliniň barypha 1940-njy ýyllarda orta atan ýalňyş çaklamasyndan nämüçindir henizem saplanyp bilenoklar. Sözümizi jemläp aýtsak, Keminäniň doglan ýeri Ahal, ýatan ýeri Sarahs topragydyr. Mollanepesiň doglan ýeri Ahal, jaýlanan ýeri Marydyr. Ýöne welin, Sarahsda mesgen tutan teke türkmenlerine-de parahat durmuş miýesser etmändir. 1855-nji ýylda Hywa hany Muhammet Emin han Sarahsa goşun çekip gelýär. Gowşut hanyň baştutanlygynda tekeler ýeňiş gazanypdyrlar. Hywa zulmyndan dynan hem bolsalar, olar Eýran tarapyndan abanýan howpdan halas bolup bilmändirler. Şonuň üçinem 1857-nji ýylda Mara göçýärler. Netijede, şondan öň Maryda oturan saryklar ýokaryk süýşüp başlaýarlar. Ýolötende oturan salyrlar bolsa Eýranyň Zutabat diýen ýerine göçüp gidýärler. Salyrlar Zurabatda on iki ýyl oturypdyrlar. Emma oturan ýerleriniň daglyk, ekin üçin ýaramaz bolandygy zerarly Gerurut–Tejen derýasynyň sag tarapyna goýbermeklerini Eýran häkimlerinden haýyş edipdirler. Eýran äkimleri olara: Eger-de saryklaryň we tekeleriň alamançylygyndan serhedi goramakdygyňyzy boýnuňyza alsaňyz goýbereli‖ diýipdirler. Salyrlar muňa bialaç boýun bolupdyrlar. Muňa gahar edip tekeler salyrlaryň tas, ähli mallaryny diýen ýaly sürüp gaýdypdyrlar we diňe hemmesi Mara göçüp gelen agdaýynda mallaryny dolap berjekdiklerini aýdypdyrlar. Şeýlelikde,