INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (96,1,96,'Şol wagt Hywa hanlygyna garaşlydygyna garamanan, Sarahsda han düzgünine degişli hiç hili administratiw döwlet strukturalary ýok ekeni. Zurabatda oturan döwürlerem, ol ýerden soňky gezek Sarahsa göçüp gelenlerinden soňam, salyrlaryň ýeke-täk, umumy hanlarynyň bolmandygyny, Teke hana Garamanyň we Ýalowajyň bir böleginiň, Meňli hahana-da Kiçiaganyň we ýalawajyň bir böleginiň boýun egendigini kiçiagaly daýhan Myrat Berdiýew özüniň otuzynjy ýyllarda beren maglumatynda ýatlaýar. 1 Ýöne, Eýran raýatlygyndan çykyp, Orsyýede birikmek isleýändiklerini bildirip ýazan arzalarynda, Teke han salyryň umumy hany hökmünde gol çekipdir. Öz möhrüni basypdyr. Meňli hanyň bolsa umumy gol çekenleriň arasynda ady hem ýok. Diýmek, şol döwür salyrlarda umumy han, kazy, kethuda, molla diýen ýaly bir agza bakdyryjylyk elementleri ýüze çykyp ugrapdyr. Bu – raýat bolup oturan döwletleriniň täsiri bolmagam mümkin. Umumy han bellemek meselesi welin, gürrüňçileriň belleýişleri ýaly öňürti hakykatdanam Gowşut han tarapyndan amala aşyrylan bolmagam mümkin. Çünki, Gowşut düşünjeli, progressiw häsiýetli adam we güýçli serkerde bolupdyr. Agzalaçylygyň, böltekçiligiň türkmen halky üçin baryp ýatan betbagtçylykdygyna düşünipdir. Galyberse-de, ―hemsaýaryny‖ göz astynda saklamak üçinem oňa ýeke-täk han zerur bolupdyr. Ýöne, biz Teke hanyň Zurabatda birinji gezek oturylan döwri Maşat hany /ýöne, ol wagt Alymerdan han däl/ tarapyndan umumy han hökmünde bellenen bolmagynyň mümkindigini hem aradan aýyrmaýarys. Çünki, şol on iki ýylyň dowamynda Teke han tamynan 28-40 ýaşlaryndaky adam bolýar. Şamman aganyň tassyklamagyna görä, Teke hanyň kakasy Nazarmuhammet hanyň ýogalan wagtam şol döwre gabat gelýär. Meňli han bolsa ömrüniň 8 – ýaşdan – 20-ä çenli bolan aralygyny şol ýerde geçirýär. Onuňam öz obasyna Zurabatda otyrkalar ýa-da Mara gelensoňlar han saýlanan bolmagy mümkin. Ýöne, nirede saýlansa-da, tä Teke han hanlygyny tabşyrýança, ol umumy han hökmünde ykrar edilmändir. Emma teke hana boýunam bolmandyr. Çünki, taryhyň gatlaryna siňe seredenimizde ol bize gara ýüzüni ýalpyldadyp Teke handan ýa gara görnüm yzda, ýa-da ýeňsesini tüňňerdip at gaýtarym öňde görünýär. Marydan Zurabada gidilende-de ol öz tiresini alyp öňürti gidýär, Zurabatdan Sarahsa gaýdylanda-da öz obasy bilen biraz soň göçüp gaýdýar.

