INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (97,1,97,'Howwa, salyrlar Maryda on ýyl oturypdyrlar we diňe Gökdepe söweşinden soň, Dykma serdaryň haýyşy boýnça Mary kethudalary salyrlary Sarahsa goýberipdirler. Bu mesele boýunça Dykma serdaryň ýanyna Teke hanyň hut özi gidipdir. Emma Horasan walisi salyr ýaşulylarynyň, han-begleriniň köpüsini para-peşgeş bilen satyn alypdyr, uly baýlyk, gönenç wada beripdir, jažykhužuk edipdir we olary bu gezgem Zurabada gitmeklige yrypdyrlar. Hususanam, Eýran häkimleri: ―Derýanyň sag kenarynda biz öz halkymyzy ýerleşdirjek, siz Horasana degişli Zurabada baryň‖ diýýärler we şondan soň Tejen derýasynyň sag kenarynda Ruknabat berkitmesini gurdurýar. Emma ol berkitmäniň gurluşygyny olar ors hökümetiniň gysyşy boýunça bes etmeli bolýarlar. Indi ikinji gezek aldanyp Zurabada gidilmeginde Teke hanyňam günäsi ýok däldir. Ýöne, birbada onuň Orsyýede raýat bolmaklygy gümürtikgräk gören bolmagam mümkin. Her-hal, salyrlar şol gezek Pulhatyndan geçip, Gerurur derýasynyň çep kenary bilen ýene-de Zurabada tarap ýola düşüpdir. Şol wagt Teke han 50-51, Meňli han 30-31 ýaşlarynda bolmaly. Emma Maşat hany Alymerdan han olara bu gezgem ekin üçin gowy ýer bermändir. Çybyn-çirkeýli, gamyş, ot basan, şorlap ýatan ýer beripdir. Her dürli keseller ýüze çykypdyr. Ozaldan ezenegi agan halk açlykdan, horlukdan heläk bolupdyr. Köp adam gyrlypdyr. Ýaz çykansoň Eýran häkimlerinden karzyna tohumlyk bugdaý, işçi mal alyp ekin ekipdirler. Emma şor ýerde ekin bitmändir. Bitse-de hasyl bermändir. Olar hatda tohumlyk diýip alan karzlarynam üzüp bilmändirler. Üstesine ýerli halk bilen oňşuklaram o diýen öwerlikli bolmandyr. Olar-a bularyň üstünden agalyk etjek bolupdyrlar, bularam olara boýun bolmajak bolupdyrlar. Eýran häkimleri salyrlary göz astynda saklamak üçin Zurabatda Meňli hanyň öz obasy bilen aýratynlykda oturýan ýeri bolan Garadepede birnäçe berkitme gurup, harby garnizon döredipdir. Garnizonda edýän serbazlar ―gelmişe