INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (99,1,99,'Teke han Eýranda, Pendide, Çärjewde galan, Owganystana giden we başga-da dürli ýerlere dargan salyrlara adam iberipdir we olaryň aglabasyny ―Kärizlä‖ ýygnapdyr. Şol ýerdenem hemmesini Sarahsa, häzirki oturan ýerlerine göçürip getiripdir. Şondan soň Teke han gadymky Salyrýap suw sistemasyny täzeden bejerdipdir, arassalapdyr. Ýeri bölmek üçin Salyrýapdan gaýdan esasy üç ýaby salyryň üç obasynyň arasynda bije atypdyr. Birinji bije: ýokarky ýap – Ýalowaja düşýär. Ikinji bije: ortaky ýap – Kiçiaga düşýär. Üçünji bije: ilerki ýap – Garamana düşýär. Ýaplaryň bije atylyşy barada şeýleräk gürrüň bar: ýagny, Mary bazarynda Sarahs ýurduna belet biri Sarahsdan gelen bir adam bilen söhbetdeş bolýar. Söhbetiň soňy Sarahsdaky ýap bölünişigine syrygýar. – Ýokarky ýap kime düşdi? – Ýalowaja. – Hä-ä... Ýalowaç ýere eýe boldy diýsene. A ortaky ýap kime düşdi? – Kiçiaga. – Ähä-ä.. Kiçaaga suwa eýe boldy diýsene. Eýse ilerki ýap kime düşdi? – Garamana. – Hm-m... Garaman pula eýe boldy diýsene. Bu hekaýatyň Manysy şeýleräk: Ýalowaç ýere eýe bolupdyr diýmeginiň sebäbi – oňa düşen ýer gowy. Mes. Giň. Tekiz. Kiçiaga suwa eýe bolupdyr diýmeginiň sebäbi – ol ýap göni. Gidişi pesaşak. Suwy akgynly. Garaman pula eýe bolupdyr diýmeginiň sebäbi, oňa düşen ýer Eýran bilen serhetdeş. Eýran Sarhasy, Maşat ýaly uly bazarly şäherleriň alkymy. Söwda üçin amatly. Üstesine-de Eýran bilen aralygy Weeňňämden başlap, tä Kindiklä çenli bir gezek suwaryp ekip bilseň, ähli ekin düme bitýä. Salyrlaryň baýy Garamandadyr diýilmegem şonuň üçin. Şondan soň Teke han: ―Haýsy milletdendigine, türkmeniň havsy taýpasyndandygyna

