INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (100,1,100,'garamanan, kim hünärli bolsa, daýhan bolsa, mirap ýa söwdegär bolsa gelibersin, biz Sarahsda ýurt tutdyk, ýap gazdyk, çil çekdik, ýer kän, ýer diýene ýer, suw diýene – suw berjek‖ diýip, çar tarapa jar çekdirýär. Çaparlar gönderýär. Bu habary eşidip salyrlaryň Eýranda, Owganda, Pendide galangaçanlaryndan başga-da, dürli milletlerden kän-kän adam Sarahs topragyna ýygnanypdyr. Ýeri gelende aýtsak, 1885-nji ýylda, Ýolöten etrabynyň Dädeguly obasynda eneden bolan Molamurt şähyr hem şol göç-hä-göçlükde, has takygy ikinji gezek Sarahsa – Zurabada gidişlik döwründe Pendide galan Hojanyýaz atly bendäniň ogludyr. Onuň hossarlary salyryň Sarahsa ýygnanandygyny eşidip gelýärler. Indi bolsa salyrlaryň Zurabatdan Sarahsa göçüp gelişleri baradaky dokumental maglumatlara garap eçeliň. 1884-nji ýylyň başynda, Mary geňeşi Ak patyşanyň raýatlygyny kabul edenden soň, Eýran hökümeti Köne Sarahs topragy üçin ynjalyksyzlanyp başlaýar. Bu oazisi Orsyýetden öňürti ―özleşdirmek‖ maksady bilen Horasanyň general-gübernatoryna gyssagly suratda görkezme berýär. Şu iş üçin hiç-hili çykdajydan gaçmazlygy buýurýar. Bu ýagdaý Orsyýediň Tährandaky ilçisi Melnikowa mälim bolýar we 1884-nji ýylyň 13-nji maýynda Zakaspiý o blastynyň naçalnigine telegramma iberýär. Şeýle hem Peterburga habar edip, parslaryň bu tutumyna päsgel berer ýaly, Sarahsy eýýäm Orsyýediň raýatlygyny kabul eden Mary tekelerinden we saryklardan doldurmaga rugsat sorandygyny mälim edýär.1 Kawkaz harby okrugynyň komanduýuşisi Knýaz Dondukowyň ýokarky telegramma beren jogabynda bolsa, 1884-nji ýylyň 28-nji maýynda, Maryda oturan salyrlardan iki ýüz öýlüniň eýýäm Sarahsa ugradylandygyny gorag üçin gapdallaryna her biri ýüz atlydan ybarat iki sany kazak ottýadynyň goşulandygy beýan edilýär. Marydan gaýdan iki ýüz öýlüni goraglap gelen otrýadyň komandiri podpolkownik Alyhanow özüniň atlylary bilen 31-nji maýda eýýäm Tejen derýasynyň sag ken