INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (102,1,102,'Şondan soň Zurabatda oturan salyrlar derýanyň sag knaryna geçmek üçin gyssanmaç suratda göç urup başlaýarlar. Muny duýan Eýran hökümeti hem olara päsgel bermek üçin taýýarlyk işlerine girişýärler. Alymerdan han alty ýüz nöker we dört sany top bilen Maşatdan çykýar we Zurabada tarap ýola düşýär. Şol aralykda Alyanow Köne Sarahsy, Gowşuthangalany, Hangalany, Ruknabady doly gözegçilik astynda saklaýar. Agzalan galalaryň hersinde bir wzwod garawulçylyk çekýär we her üç günden bir gezek çalyşýar. Esasy güýç Köne Sarahsda saklanýar. 1884-nji ýylyň 5-nji iýun güni, Teke han ýüzlerçe öýli salyr bilen derýadan urup geçýär we Köne Sarahsyň garşysynda ýerleşýär. Salyrlaryň galan esasy bölegi Alymerdan han gelip ýetişmezden öň birgiden mal, goş-golam, çaga-çuga, aýal-ebtat bilen yzanda-çuwan bolşup, 8-nji iýun güni gyr-gyssag Gyzylgaýany nazarlap, Zurabatdan göterilýär. Olar kowgydan gutulmak üçin, ―Pulhatyn‖ köprüsine barmaga-da howlugyp derýadan urup geçýärler. Daglaryň ýüzünden nägehan sil suwunyň inýän döwrüdigini ýada salsaň, joşgunly derýadan müňlerçe adamy birgiden malgarasy bilen geçirmekligiň nähili güzaply bolandygyny, nijembir ýitgileriň çekilendigini göz öňüne getirmek kyn däl. Alymerdan hanyň kowgy gidendigi baradaky habar gulagyna degenden, Alyhanow hem iki ýüz atlysy bilen Ruknabatdan çykyp ýola düşýär we derýanyň çep kenaryny syryp, bosgunlary yzarlap gelýän Alymerdan hanyň we salyrlaryň arasyna girýär. Ýagdaýdan habardar edilen Eýran şasy Tährandaky ors ilçisi Melnikowdan Alyhanowyň otrýadyny ortadan aýyrmaklygy talap edýär. Emma kanagatlanarlykly jogap alyp bilmeýär. Alymerdan han hiç-hili uruş meýillerini ýüze çykarmaýar we assaýuwaş çep kenardan daşlaşmak bilen bolýar. Öz berkitmesine barandan soň ol Ruknabady orslara bermekde aýyplap, üç sany pars ofiserini tussag edýär. Alyhanow hem öz kazaklary bilen atynyň başyny Köne Sarahsa tarap öwürýär. 12-nji iýuna sal