INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (106,1,106,'Bilşimiz ýaly, XIX asyryň ortalaryndan başlap, Hazarý deňziniň kenar ýakalarynda oturýan ýomut türkmenleriniň hany Kaýat han Ors hökümetinden otuz ýyllap birsyhly raýatlyk sorap gelipdi we hiç-hili kanagatlanarlykly jogap alyp bilmändi. Şonda ak patyşanyň hökümet ýolbaşçylary, hususan-da maliýe ministri, türkmenleriň yzagalak, medenýetsiz halkdygyny, eger-de raýatlyga kabul edäýseler, onda olara mekdep, keselhana, poçta, telegraf, dükan ýaly derwaýys desgalary, administratiw merkezleri, şeýle hem demirýol gurmaly boljakdygyny, o zatlaryňam ummasyz çykdajylara talap etjekdigini bahana edipdiler we raýatlyga kabul etmekden kes-kelläm ýüz öwrüpdiler. Ine, birdenem olar ýap-ýaňyja-da aýakbagy hasap edip oturan halkynyň üstüne sürnüp ugradylar. Öň parslara wehim salmak üçin Astrabatda guran gämi duralgalaryny ur-tut Şagadama /Krasnowodsk/ geçirdiler. Şol ýerde durup, tutuş türkmen sährasynyň üstaşyry tä, Guşga çenli göz dikdiler we äpet aždarha kimin agyzlaryndan ot saçyp, Garagumuň gyzgyn çägeleriniň üsti bilen günorta tarap süýşüp başladylar. Ýöne, türkmen sährasy boş däldi. Onuň üstünde entek Skobelew tarapyndan ruhy öldürilmedik sähraýy türkmen göçi agyp-dönüp ýördi. Onuň üstüni basyp ötübermek aňsat däldi. Garşylyga duçar boljakdyklaryna orslaryň özleriniňem gözleri ýetýärdi. Esasanam olar özlerine garşy Ahal hem-de Mary tekeleriniň garyndaşlyk esasynda birikmeklerinden ätiýaç edýärdiler. Şonuň üçinem baran ýerlerinde özleriniň basybalyjylykly meýillerini gizlemäge çalyşýardylar. Bu topraga ýagşy niýet bilen gadam basýandyklaryny, hususan-da Hazardan geçip şu toprak üzre, eýýäm öz raýatlygyny kabul eden Hywa hanlygyna tarap söwda hem-de diplomatik gatnaşyklary amala aşyrmak isleýändiklerini, şonuň üçinem bu ýoluň howp-hatardan halas bolmagyny üpjün etmek üçin bu ýurtda öz tertip-düzgünlerini ýola goýmak meýilleriniň bardygyny, ol çäräniň öňi bilen türkmenleriň özleri ü