INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (107,1,107,'bölüminiň wagtlaýyn komanduýuşisiniň 1880-nji ýylyň 2-nji iýunynda Orsyýetiň Eýrandaky ilçisine iberen telegrammasynda şeýle diýilýär: ―Kömegiňiz üçin sag boluň. Kuçanly we Büjnürtli tekeleriň üstüne çapawulçylygy häzirem, bütin güýzüň dowamynda-da bes etmeli däl. Çünki, biz özümiz-ä tyl işleri bilen başagaý. Ýagny, ülkäni Gökdepä çenli-hä tozdurdyk. Gökdepe bilen Aşgabat aralygyny tozdurmaga-da Horasanly kürtleri küşgürip bilseňiz iş bitirdigiňiz bolardy. Olara tabşyryň: tekeleriň gyş azyklaryny we öý goşlaryny ýaksynlar, mallaryny talasynlar. Şu zatlary birkemsiz berjaý edip bilseler, bizem öz gezegimizde kürtleriň gadryny bileris. Çapawulçylyk üçin Ýarmuhammet hana ok, däri, ýarag ýetmezçilik edýän bolsa aýdyň, kömek ederis1‖. Şu hili ýollar bilen gidip baryşlaryna türkmenleriň başyna Gökdepe tragediýasyny salan, Gowşut hanyň, Nurberdi hanyň syrly ölümlerine sebäp bolan ors häkimiýetiniň ýaragly güýçleri sähelçe wagtyň içinde Krasnowodskiden Guşga çenli baryp ýetdi. Eýsem bu galagoplugyň, urdumşalygyň, eden-etdiligiň, şeýle howlukmaçlygyň aňyrsynda nämeler ýatyrka? Sebäbi nämedekä? Ýa ahyrsoňunda ak patyşanyň türkmenlere rehimi inäýdimikä? Ýa birdenkä Türkmenistanyň ýerasty baýlyklary böwürlerine dürtüberdimikä? Ýok! Olaryň ol wagt türkmenlere rehimem inenokdy, Garagumuň aşagyndaky ummasyz baýlygyň ýatandygyndanam habarlary ýokdy. Belanyň körügi başga tarapdady. Bu zatlaryň barsynyň aňyrsynda, Orsyýet bilen Ang;iýanyň arasynda duýdansyz dörän bäsleşik ýatyrdy. Ýagny, iňlisler Hindistanyň üsti bilen Owganystana dykylyp gelipdiler. 1878-nji ýylyň aýagynda Kabuly, Gandahary eýeläpdiler. eger-de Hyradam alaýsalar, onda olaram edil Orsyýediň öz edişi ýaly Orta Aziýa, şol sanda Türkmenistana hem süsňäp girjekdiler we netijede tä, Hazarý deňzine çenli bolan aralyk olaryň eline geçjekdi. Deňziň aňry ýüzi bolsa orslaryňkydy. Sähelçe haýalýagallyga ýol berdikleri iňlis şiri b