INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (113,1,113,'milisiýanyň ştabs kapitany ýaly ikinji, üçünji derejeli diňe dikme baýarlaryň ýörelgesi bilen ýörelýän wezipelere bellenip, erk-ygtyýarlarynyň ellerinden alynmagyny bolsa olaryň hersi birhili kabul etdi. kimsi janynyň ýangynjyna hakykatdanam iňlisler bilen ―hajyk-hujuk‖ edişdi, kimsi ak patyşa bilen öçli bolup, atymyna gelen güni ýaraga ýapyşdy, gozgalaň turuzdy, kimsi oňa ak ýürekden gulluk etdi, kimselerem derdini ýüregine sygdyrybilmän ruhy yzalar çekdi we şol yzadanam ýogaldy. Eýsem Teke han şol adamlaryň haýsy biriniň hilindenkä? Nuktaý-nazarymyzyň has töwerekleýin bolary ýaly, geliň, Teke han, Meňli han barada Söwet döwründe çap bolan materiallar bilenem tanyş bolalyň. Şol dokumentlerde köplenç, Teke handyr, Meňli hanyňam edil, beýleki türkmen hanlary ýaly ýerli häkimiýetlere daýanyp eden-etdiliklere ýüz urýandyklary barada aýdylýar. Mysal üçin, ýerli baýlara garşy çykyş edendikleri sebäpli ýerli häkimiýetler tarapyndan tussag edilen daýhanlary tussaglykdan boşatmak hakyndaky haýyş bilen, 1903-nji ýylyň 20-nji maýynda ýazylan arzada şeýle diýilýär: ―Ýalawaç obasynyň ýaşaýjylary bolan biziň kime degişlidigi nämälim ýerimiz bardy /Bölünmedik we işlenip bejerilmedik obşina göz öňüne tutulýar. Düzüjileriň belligi/ Näme üçindir Meňli han we Teke han ol ýere ekin ekdiler; Pristawyň kömekçisi Teke hany biz ekin meýdanyna goýbermedik. Ol öý eýesi bolup durýan hem bolsa, bizi häkimiýete garşylyk görkezmekde aýpladylar. Käbirlerimizi tussag etdiler, häzir 24-imiz tussaglykda otyr, ekerançylyk işinden çetleşdirildi, iş hiç-hili seljerilenok. Tussaglykdan derrew boşatmak bilen işiň seljerilmegi çaltlandyryp ilaty goramagyňyzy siziň alyjenabyňyzdan haýyş edýäris, bugdaý bişýär – dänesiniň dökülmegi mümkin.1 1905-nji ýylyň 21-nji iýunynda Meňli hana degişli suwy eýeländikleri üçin daýhanlaryň bir toparyny tussag etmek hakynda Saragt pristawynyň wezipesini ýerine ýetiriji, /tussag etmek hakynda/ ştabs – kapitan Karpinskiýniň çykaran kararynda bolsa şeýle diýilýär: ―Zakaspiý oblasty boýunça 1903-nji ýylyň 6-njy iýunyndaky 181-nji buýrugyň 2-nji punkty esasynda 1905-nji ýylyň 21-nji iýun güni Saragtyň pristawy, ştabs-kapitan Karpinskiý Meňli hanyň bolmazlygyndan peýdalanyp, ekinleri nobatdaky 1 Türkmenistanyň taryhy boýunça hrestomatiýa. Düzüjiler: N.Rahymow, S.Weliýew, P. Goýunlyýew. Aşgabat. Magaryf. 1992 ý. 197 sah.

