INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (123,1,123,'Ýeri gelende aýtsak, tire-taýpa serdarlarynyň ýa-da ata-babalarynyň kultuna sejde etmek, olary hudaýlaşdyrmak edähedi doly suratda döwrebaplaşmadyk, medeni hem tehniki taýdan yza galan käbir Afrika ýurtlarynda häzirem dowam edýär. Şoňa golaýrak ýagdaýyň bir ujy Türkmenbaşynyň zamanasynda onuň heýjanelekçileri tarapyndan biziň hut öz ýurdumyzda hem çalarak ýüz berip geçip gitdi. Gadymyýetden getirilen ýokarky tymsallar bolsa, adamzadyň entek Hudaýyň birdigine akyl ýetirip bilmedik döwürlerine mahsus zatlardyr. Ynsan diňe özüniň aň-düşünje taýdan has ösmegi netijesinde Hudaýyň birdigine, ähli halklaryň diňe bir Hudaýa uýmalydyklaryna kemkemden göz ýetirip başlapdyr. Şeýle düşünjä ymtylmaklygyň, ýagny monoteizmiň ilkinji alamatlary juda ýöntem görünýän hem bolsa, hut politeizm döwründe ýüz berip başlapdyr. Mysal üçin, gadymy ýunan taýpalarynyň ählisi öz Hudaýlaryny bir ýere – panteonlara jemläpdirler, haýsy taýpa güýçli bolsa, şol taýpanyň Hudaýy ähli taýpalaryň başlygy diýlip yglan edipdirler. Şu ýagdaý arap dünýäsinde hem tä yslama çenli dowam edipdir. Muhammet pygamber hem hut şol köphudaýlygy ýok etmek, bir hudaýlylygy girizmek nukdaý nazaryndan ugur alandyr. Çünki, ol köphudaýlylygyň araplara agzalalyk getirýändigini, bir Hudaýa ynanmaklygyň ýeke bir ruhy, ahlaky taýdan däl, eýsem ykdysady, söwda, medeni taýdan hem ösüşlere alyp barjakdygyna düşünipdir. Ýöne, ylymda monoteizmi ilkinji bolup esaslandyranlar ýewreýlerdir. Onuň gözbaşynda Musa (Injilde Moniseý) pygamber dur. Miladydan öňki II müňýyllykda dörän bu dine ýehudyçylyk (Pudaizm) diýilýär. Ol diniň ýörelge – taglymaty bolan, Musa pygambere Tur dagynyň başynda Hudaýtarapyn inen ―On pendiň‖ birinjisinde şeýle kelam bar: ―Men seniň Hudaýyňdyryn. Sen menden gaýry Hudaýy – Hudaý tutnmaly dälsiň‖. Pendiň ikinjisinde bolsa: ―Ne asmandaky, ne zeminiň üstündäki we astyndaky, ne suwdaky zatlardan doňňara (idol) ýasap, olary özüňe hudaý saýma‖ diýipdir. Bu dini dünýäde köphudaýlylyga urlan ilkinji we aýgytlaýjy zarbadyr. Ýöne, Musa pygamberden öň ýaşap geçen Nuh (Injilde Noý), Ybraýym (Injilde Awraam), Ýakup (Injilde Iakow) dagylar hem halky

123',2131);
INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (124,1,124,'birhudaýlylyga ündän pygamberlerdir. Adam ata bolsa Allanyň ýer ýüzündäki ilkinji resulydyr. Gynansak-da, Adam ata bilen Nuh pygambere çenli bolan taryhyny adamzat ýadyndan çykarypdyr. Ýehudyçylygyň yz ýany dörän uly bir din – bu otparazçylykdyr, ýagny, zoroastrizmdir. Ony esaslandyryjy Zoratuştradyr. Bu din öz tebigaty boýunça dualistik häsiýetlidir. Ýagny, onuň mukaddes kitaby bolan Awesta, ýagşylyk bilen ýamanlygyň baky göreşi baradaky pelsepä ýugrulandyr. Ol oduň Hudaýy Ahura – Manany ähli güýçlerden ýokarda goýýan hem bolsa, Arduwe – Sure derýasyny (häzirki Amyderýa) we käbir dag-deňizleri (Worokuşa – Aral deňzi) hem mukaddes hasap edýär. Günorta we Gündogar Aziýanyň uly ýerlerinde emele gelen jemgyýetçilik kadalaryny we tertip-düzgünlerini gorar ýaly olaryň eldegrilmesizliklerini üpjün eder ýaly hem birnäçe politeistik dini akymlar ýüze çykypdyr. Mysal üçin, Hindistanda brahmanizm, induizm, jaýnizm, sikhizm we ş.m. Miladydan öňki IV–III we VI–V asyrlarda Hytaýda emele gelen iki sany pelsepeýi – etiki ugur konfusiançylyk (konfusianstwo) we daoçylyk (daosizm) hem kem-kemden dini akymlara öwrülip gidipdirler. Ýaponiýada aýal hudaý Amaterasunyň neslinden hasap edilýän imperatoryň kultyny esas edinen sintoizm ýüze çykypdyr. Musaýyçylykdanam (iudaizm), Buddaçylykdanam (buddizm), isaýyçylykdanam (hristianstwo) has ir dörän krişnaçylyk (krişnaizm) dini Krişnany transsendental, jümle-jahandaky ähli planetalaryň ählisiniň hudaýlarynyň Hudaýy, iň güýçlisi iň arassasy, ähli zatlaryň gözbaşy, beýigi hasap edýär. Krişna baradaky taglymat ýeriň ýüzünde mundan bäş müň ýyl öň dörän hem bolsa, Krişnanyň özüniň akyl ýetirerden has irki döwürlerden bäri bardygyny, onuň her brahma güni, ýagny, her 600.000.000 ýyldan bir gezek biziň planetamyza adamzady heläkçilikden gutarmak üçin gelýändigini krişnaçylar terkarlaýarlar we onuň soňky gezek mundan 5 000 ýyl ozal gelendigini, şu wagtky bar bolan taglymatyny hem hut özüniň, şol gezek galdyryň gidendigini, şeýle hem onuň hemişe biziň ýanymyzdadygyny ündeýärler. Bu dini taglymat boýunça adam ölenden soň onuň ruhy başga bir predmete ýa-da başga bir jandara geçýär.

