INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (126,1,126,'Dünýä dinleriniň iň ýaşy yslamdyr. Bu din VII asyrda Arabystanda Muhammet pygamber tarapyndan esaslandyrylýär. Döränden soň köp wagt geçmänkä, üç sany ugra – sünnülere, şaýylara we haryjlara bölünen hem bolsa, yslamda esasy ugur hökmünde rowaçlanan şahalar – sünni we şaýy mezhepleridir. Kuranda görkezilmedik hem bolsa, sünniler Muhammet aleýhyssalam tarapyndan ýerine ýetirilen dini işleri – sünneti amala aşyrmaklygy hem özlerine parz hasap edýärler. Şaýylar bolsa, sünnetiň diňe dördünji halyf Hezreti Ala degişli ýerlerini ýerine ýetirmekligi özlerine parz bilýärler. Sünni bilen şaýy şahalary hem öz gezeklerinde dürli böleklere bölünýärler. Mysal üçin sünnilerden wähäbiler bölünip çykan bolsalar, şaýylardan zeýdiler, ysmaýyllylar bölünipdirler. Zeýdiler sünnilere golaýrak bolupdyrlar. Ysmaýyllylaryň taglymatlarynda bolsa neoplatonizmiň (eflatunçylyk) gnostisizmiň, buddizmiň täsiri açyk duýlupdyr. Öz gezeginde ysmaýylylardan hem druzlar, nusaýritler (alawitler) ýaly etnokonfessional toparlar emele gelipdir. Dini daragtlaryň, olaryň şahalarynyň we pudaklarynyň ýaýrawam, täsirem dürli-dürli. Käbir akymlaryň ygtykatçylarynyň sany ýüzlerçe ýa-da onlarça adamdan artyk däldigini ylmy çeşmeler habar berýärler. Şonuň üçinem, biz şu ýerde umumyadamzat dinine öwrülen üç dine – Buddizme, isaýyçylyga, yslama uýan adamlaryň ýer ýüzi boýunça umumy sany baradaky maglumatlary hem getirmekligi makul bildik. 1980-nji ýylda geçirilen hasabata görä, ýer ýüzündäki dindarlaryň iň köpi isaýylar (hristianlar) bolup, olaryň sany 1433 mln.. Ondan soňky orny sany 732 mnl. bolan musulmanlar eýeläpdirler. Üçünji ýerde induistler barýarlar. Dünýä dinine öwrülmedik hem bolsa olaryň sany buddaçylaryňkydan köp, ýagny, 583 mln. adam. Buddaçylar – 274 mln; Konfusiýaçylar we daoçylar 203 mln; Ýehudylar – 17 mln; (Şunuň dünýä dinleriniň hataryna goşulýan halatlaryna-da duş gelmek bolýar). Sikhler – 14 mln; Jaýnlar – 3 mln. Hristianlaryň içinde iň köpi katoliklerdir. Olaryň sany 809 mln.

