INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (127,1,127,'Protestantlar – 426 mln. Prawoslawlar – 124 mln. Musulmanlaryň aglabasy sünniler bolup, şaýylar musulman ähliniň ondan bir bölegine barabardyrlar. Şu ýerde özi ýitip, diňe owazasy galan Taňryçylyk (Gök taňry) dini barada hem iki agyz aýdyp geçmegimiz gerek. Taňry – asman diýmek bolup, ol türki halklaryň gadymy dinidir. Özi döredimi ýa öňden gelýän dine uýupmy, hersi bir zada sejde edip ýören oguzlary – türkileri taňryçylyk dinine, ýagny, bir hudaýlylyga salan Oguz handyr. Şonuň üçinem ol pygamber ornunda goýulmagy şahsyýetdir. Oguzlary Oguz hanyň taňryçylyk dinine uýdurandygy baradaky maglumata biz Oguznamada hem duş gelýäris. Ýaşynyň soňunda Oguz han ogullaryna şeýle diýýär: Dostlarymy men güldürdim. Duşmanlarymy men aglatdym, Gök taňryga gulluk etdim, Sizlerge men berýän ýurdum. Taňry sözi türkmenleriň, şol sanda türki halklaryň arasynda henize çenli Hudaý Manysynda ulanylyp gelinýär. Ýagny, ―Eý Hudaý‖, diýen söze derek, siz ―Eý, taňrym‖, ―Alla ýalkasyn‖ diýen söze derek ―Taňry ýalkasyn‖ diýen sözi köp eşidýänsiňiz. Nusgawy şahyrlarymyzyň goşgularynda hem ―taňry‖ sözi köp duş gelýär. Mysal üçin, Magtymguly?: Taňry bermese nädeli, Baş alyp nirä gideli, Oturyp-turşy edaly Gaşlary galam islärin. diýýär. Şeýle mysallary başga-da näçe getirseň getirip oturmaly. Dünýä dinleri baradaky gysgaça maglumatymyz ine, şulardan ybarat. 1998ý.

