INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (128,1,128,'2. Yslam surat çekmekligi gadagan edipmi? Şolar ýaly düşünje halk arasynda bar. Ony biz özümizem çagalykdan bäri eşidip ýörüs. ―Bu dünýäde adamyň suratyny çerkseň o dünýäde oňa öz janyňy bermelimişiň‖, diýen ýaly sözlerem gulagymyza degýärdi. Ýöne, surat çekmekligi gönüden-göni gadagan ediji hiç hili kada kanunyň ne yslamyň ýörelgesi bolan Kurany kerimde, ne hadyslarda ýokdygyny şol taglymaty öwreniji alymlar aýdýarlar. Ýöne, gadagançylyk barada aýdylýan gürrüňleriň düýbünde esas ýok hem däl. Ýagny, Muhammet aleýhyssalam özüniň ýalowaçlyga başlan döwürlerinde, öňi bilen isaýyçylygy restawrasiýa etmekden başlapdyr. Isaýyçylaryň öz pygamberlerine Hudaý, Hudaýyň ogly diýmeklerini düýpgöter unamandyr. Çünki, onuň öz taglymaty boýunça Hudaý doglanogam, dogranogam, onuň ilen-çalanam ýok. Ol Ýeketäk güýç. Üstesine isaýylar Isa pygamberiň suratyny dullaryndan asyp, Hudaý hökmünde sejde edýärler, çokunýarlar. Bu bolsa Muhammet aleýhyssalamyň täze taglymatyna düýbünden gabat gelmeýär. Birnäçe wagt geçenden soň, täze nesilleriň surata seredip: ―Pygamberimizem biz ýaly adam ekeni‖ diýmekdirlerini öz aralaryndan kimdir biirne meňzetmeklerini islemändir. Hudaýyň dosty bolup, Onuň kada-kanunlaryny adamlaryň arasynda wagyz eden ynsanyň halkyň diňe aňynda ýaşamagyny isläpdir. Şeýle-de ol yslamdan öňki arap dünýäsinde idollaryň hudaý saýylmagyna garşy juda erjel göreşipdir. Şonuň üçinem, ol yslama şekillendiriş sungaty babatda gadagançylyk girizipdir diýen ýalňyş düşünje döräpdir. Yslam özbaşdak din hökmünde pajarlap dünýä gelenden soň hem pygamber aleýhyssalam şekil babatdaky öz pikirini birsyhly berkidip gelipdir. Şekillendiriş sungatynyň yslamda gadagan edilmändigini subut ediji tymsallar sanap çykardan kän. Mysal üçin, musulman äleminiň iň güýçli pirleriniň biri, XIV asyrda osmanly ýurdunda ýaşap geçen möwlana Jelaleddin Rumynyň bir gürji hudožnigine öz suratyny çekdirendigi barada maglumat bar. Osmanly türkmen patyşalarynyň ählisiniň portretler seriýasynyň bardygy hem muňa mysal hökmünde goşmak bolar.

128',2028);
INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (129,1,129,'Bu babatda esasanam orta asyrlarda ýerine ýetirilen miniatýura – žiwopis eserlerini ýatlamak ýerlikli bolar. Şol döwürler musulman dünýäsiniň Hyrat, Buhara, Samarkant, Şiraz, Töwriz ýaly şäherlerinde ýörite miniatýura – žiwopis mekdepleri bolupdyr. Şol döwrüň miniatýuraçy suratkeşleriniň arasynda türkmen hudožnigi Begzadyň ady has hem meşhur bolupdyr. XVI asyryň birinji ýarymynda Horasanda we orta Aziýada özüniň ýetjek derejesine ýeten, Demir agsak döwründäki miniatýura žiwopisiniň iň gowy nusgasy hasap edilýän eser – Alyşir Nowaýynyň Bady az-Zaman üçin 1485-nji ýylda Hyratda, gaýtadan göçürilen ―Hamsa‖ poemasyna degişli miniatýuralardyr. (Oksford uniwersitetiniň Bodleýan kitaphanasy. № 287,314,339,408) Britan muzeýinde saklanýan ―Babyrnama‖ golýazmasynda hem 96 sany miniatýura, başynda bolsa iki taraplaýyn frontispis bar. Golýazmanyň ölçegi 21x32,5 sm. Miniatýuralaryň aglabasy 15,528 sm. ölçegde. Şolaryň 78-inde awtoryň ady bar. Iki sanysy gutarylmadyk, ýagny, galam bilen kontur berlipdir-de, reňklenmändir. Bu golýazmanyň miniatýuralaryny ýerine ýetirmeklige şol döwrüň 41 sany güýçli hudožnikler gatnaşypdyr. Olaryň tas hemmesi diýen ýaly Akbaryň köşgünde işläpdirler. XV –XVI asyrlara degişli Eýran miniatýuralary barada hem şolar ýaly ýakymly sözler aýtmak mümkin. Olar: Töwriz, Şiraz şeýle hem Hyrat miniatýuraçylyk mekdeplerine degişli bolup, ―Şirin-Perhat‖, ―Leýli-Mejnun‖ dessanlaryna şeýle hem Isgender, Bährem Gur ýaly şahsyýetleriň taryhy hereketlerine Hezreti Aly, Abu Bekir, Muhammet pygamberiň sahabalary bilen bagly rowaýatlara bagyşlanyp çekilen eserlerdir. Şolaryň arasynda Töwriz miniatýuraçylyk mekdebiniň wekili, Kasym ibn Alynyň Muhammet ibn Abu Zaýda tarapyndan ýazylan: ―Ýagşyzada ymamlaryň taryhy‖ atly golýazma çeken: ―Pygamberiň iň soňky ündewi‖ atly işi hem bar. Bu kompozisiýa taýdan örän çylşyrymly, köp adamly, sünnälenip çekilen örän owadan hem çeper iş.