INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (130,1,130,'Yslam dininiň surat çekmekligi gadagan etmändigi baradaky pikirimizi tassyklaýjy ýene bir mysal. Özem häzirki döwürde, hemmämiziň gözümiziň alnynda bolup geçip duran zat. Ýagny, goňşy döwletimiz bolan, özem hut yslam döwleti adyny göterýän Eýran, her ýylda bolmasada, ýylaşa diýen ýaly Aşgabatda öz gazananlarynyň sergisini gurnaýar. Dürli pudaklara degişli häzirkizaman tehniki enjamlar senagat harytlary senetçilik sungaty halk döredijiligi bilen birlikde ol elde çekilen surat eserlerini hem görkezýär. Musulmanlaryň şaýy mezhebine uýýanlarynyň Hezreti Alynyň suratyny öýlerinden asyp goýandyklaryny hem şu aýdylanlaryň üstüne delil hökmünde goşmak bolar. Çünki, şaýylar kelemede Muhammet aleýhyssalmyň adyna derek Hezreti Alynyň adyny getirýärler. Ýagny, sünniler: Lä, ilähi illala, Muhemmedu resul Alla‖ diýseler, şaýylar?: ―Lä ilähi illalla, Aly ylla, weli ylla‖ diýýärler. Görşümiz ýaly, yslamda surat çekmeklige gadagançylyk ýok. Ol diňe Hudaýy, pygamberleri şekillendirmekligi gadagan edýär. 1999 ý. 3. Din, durmuş we adamlar. Zandy ateizme ýugrulan kommunistik sisteManyň dargamagy we SSSR-iň düzümine girýän sosialistik respublikalaryň öz özbaşdaklyklaryny yglan etmekleri netijesinde öň gadagançylyga düşen ýehudy, isaýy, yslamy dinlerine hem-de Budda uýan halklaryň dini ygtykatlaryna giň ýol açyldy. Dini azatlyk sowet döwründe beýleki respublikalara göräde has gaýymrak gysylan Türkmenistan döwletinde-de uly şowhun bilen garşy alyndy. Şäherlerde, etrap merkezlerinde, hatda birnäçe obalarda-da metjitler salyndy, medreseler açyldy, dini ugurdan okamaga höwes bildiren oglanlaryň ençemesi içinde dini okuw jaýlary bolan gaýry döwletleriň ençemesine okuwa iberildi. Şeýle okuw jaýlary indi öz döwletimiziň içinde-de peýda boldy. Şondan soň-a namaza-töwire, oraza aýada höwesek ýaşlaryň sany hasam köpeldi. Şonuň üçinem, biz şu ýerde dini-ygtykata baş goşan ýaş oglanlaryň, käbir ýagdaýla