INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (135,1,135,'Dogry, kommunistik sistema döwründe diniň gysylmagy bilen ol ugurdan dürs ylym almak, sowadyňy çykmak kyn boldy. Obalarda aýattöwüriň sähel ugruny mälim edibilýän adamlary tapmagam, zerur halatlarda musulmançylygyň iň bir ýönekeýje düzgünlerini berjaý etmegem hyllalla boldy. Kemsowat hem bolsalar şol adamlar şol döwür öz rollaryny oýnadylar. Halky kyn günleriň çykgynsyz ýagdaýlaryndan alyp çykdylar. Ýöne, indi o zatlara garşylyk ýok. Bahana-da ýok. Ýol açyk. Şonuň üçinem dini ylma, Kurana, aýat-töwüre indiden soň bir akylly-başly, hatly-sowatly çemeleşmek gerek. Ýeri gelende aýtsak, Kuranyň hökmany suratda terjime edilmelidigi, iň bolmanda onuň Many-mazmunynyň ähli halklara düşündirilmelidigi baradaky meseläni mundan tas müň ýyl ozal Türküstanda ýaşap geçen dini hadym, ―Medinede Muhammet, Türküstanda Hoja Ahmet‖ diýdiren, Hoja Ahmet Ýasawy çözüp gidipdir. Ine, ol näme diýýär: Hoşlamaýdyr alymlar bizniň aýtgan türkini, Aryflardan sorasaň açar köňül mülküni, Aýat-Kuran Manysy türki bolsa mowafeg, Manysyga düşgenler ýerge goýar burkuny. Galyberse-de, Kurany hezreti Magtymguly terjime edip gidipdir. Ol Kelamyllanyň sürelerini öz goşgularyna salyp, şahyrana setirler arkaly halk köpçüligine ýetiripdir. Sözümiz gury bolmaz ýaly mysallara ýüzleneliň. Yslam dininiň taglymatyna görä, Allatagallanyň öz bendelerinden üç talaby bar. Olaryň birinjisi ZIKR, ikinjisi ŞÜKÜR, üçünjisi PIKIR. ZIKR – bu bismiillädir. Ýagny, her bir adam her bir işi Allanyň ady bilen başlamalydyr. ŞÜKÜR – bu alhemdülillähdir. Ýagny, her bir adam her hili ýagdaýa düşse-de Allaha şükür etmelidir. PIKIR – bu dünýäde barlygyň barada, Allanyň döreden ähli naz-u-nygmatlaryndan peýdalanýandygyň barada, Asman bilen Zemin aralygyndaky ähli baýlyklaryň baýlara däl-de diňe Barhuda degişlidigi barada, hakyky mal eýesiniň Şoldugy barada pikir etmekdir. Musulman bendelerindeiň buç borjuny hezreti Magtymguly öz goşgusyny