INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (137,1,137,'dogruçyl adamlar bilen dünýewi döwlet gurmaklygyň, ykdysadyýeti, ylmy, tehnikany, medeniýeti ösdürmekligiň näderejede utuşly boljakdygyny göz öňüne getirmek kyn däl bolsa gerek. Umuman, din takyk ylymdyr we tehnika deň, biri-biri bilen ylalaşykly ösmegi gerek. Şonuň üçinem, din wekilleriniňem ylma, tehnika, edebiýata, sungata aýdym-saza şeýtany zat hökmünde garamazlyklary, jemgyýetiň ―goşa düzzüm‖ sazyny emele getirýän goşa taryň özlerine degişli tarapyny takyk bilimleriň taryndan daşlaşdyrmazlyklary gerek. Ýeri gelende aýtsak, kommunistleriň esasy betbegtçylyklary hem Hudaýy, dini düýpgöter inkär edip, adamlary wyždan yşygyndan mahrum edendikleri, goşa taryň birini beýlekisiden daşlaşdyrandyklary, netijede owaz alyp bilmändikleri bilen baglydyr. Sözümiziň soňunda bolsa türkmençiligiň toý-ýas ýörelgelerindäki käbir düşünişmezlikler barada hem birki agyz aýdyp geçmekligi makul bildik. Toýuňk-a düşnükli. Ol ýerde esasy maksat iki juwany öz razyçylyklary bilen nikalaşdyryp biri-birine gowşurmak. Toýy uly ýa kiçi tutmalydygy barada hem hiç kimiň öňünde hiç kimiň hiç hili borjy ýok. Bäş adam çagyryp ýejeke towuk soýaýanyňda hem hiç bir ýörelgä ters gelýän ýeri bolmaz. Ol her kimiň öz maddy hal-ýagdaýyna bagly. Ýöne, ine, ýasyňky welin kyn. Ruhy taýdanam, maddy taýdanam agyr. Aladasy uzak. Merhum jan teslim eden pursatyndan başlap tä ýyly geçýänçä hatda ondan soňam ýerine ýetirilmeli tertip-düzgünleriň hetdihasaby ýok. Emma şol tertip-düzgünleriň hersi, her ýerde birhili berjaý edilýär. Mysal üçin bir bende aradan çykýar. Dürli sebäplere görä, hususan-da merhumyň ýakyn hossarlarynyň gelip ýetişmedik ýagdaýynda ony bir gije, käte bolsa ondanam gowrak wagt ―myhman almaly‖ bolýar. Merhumyň özüni uzak ýurtdan getirmek üçin eglenilýän pursatlaram az bolanok. Şolar ýalyda onuň belli günlerini takyklamak meselesi dürli pikirleri ýüze çykarýar. Biri ýogalan gününden başlap hasaplama