INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (141,1,141,'Taryhdan mälim bolşy ýaly, asly hun döwletini dargadan sýanbilerden bolan Aşynanyň V a. Öz bäş ýüz öýlüsi bilen Altaý sebitlerine gelmegi, ol ýerde-de asly hun taýpalaryndan bolan aborigenler bilen garyşmagy we hytaýlylar tarapyndan özlerine dakylan ―tu-kýu‖ /türküt/ adyny olaryňam boýunlaryna dakmagy netijesinde gadymy türki taýpalar emele gelipdir. Türki sreda Altaýdan uzak günbatara – kaňlylaryň, bejeneleriň, oguzlaryň ýurduna we başga taraplara iňňän çalt ýaýrapdyr. Akademik W.W.Bartoldyň ýazmagyna görä, ähli türkiler eýýäm VI asyrda Wizantiýanyň, Hytaýyň, Eýranyň serhetlerinde bir adam ýaly hereket edipdirler. Şeýlelikde, gadymy hun taýpalarynyň dessury bolan we öz döwründe adaty zat hasap edilen dakylmak däbiniň teýi esasan hun taýpalaryndan bolan aborigenleriň üsti bilen türkütlere, olardan soň umuman türki taýpalara, assaýuwaşam oguzlara, oguzlardan bolsa häzirki türkmenlere geçen bolmaly. Özem adaty dessur hökmünde däl-de, W.A.Gordlewskiniň belleýşi ýaly, turuwbaşdan zyýanly galyndy hökmünde aslyşmak ýoly bilen geçen bolmaly. Ol dessury şondan soň her döwür, her kim özüçe gerek ýerinde ulanypdyr. Has takygy ony käbir maşgalalar çykgynsyz ýagdaýda ulanypdyrlar. Emma hiç kim, hiç haçan oňa hökmany zat hökmünde garamandyr, has takygy oňlanMandyr we ýeňňesine öýlenen ýigit türkmende hiç haçanam barmak basyp sanardan köp bolmandyr. Şeýle ýagdaý ýüze çykaýanda-da il-gün ony ýokuş görüpdir. Toý edilmändir. Nika örän sowuklyk bilen gyýlypdyr. Şeýle hem ―dakylanlaryň‖ arasynda hiç haçanam gyzgyn gatnaşyk, mähir, söýgi bolmandyr. Sowuk düşek mert ýigide hemişe agasyny, gelne bolsa başdaşyny ýatladyp durupdyr. Bu aýylganç jübütleşmäni hezreti Magtymguly şeýleräk beýan edipdir: ...Namysly goç ýigit alsa ýeňňäni, Her günde agasy ölen ýalydyr. Umuman, sözümizi jemläp aýtsak, şol kemsidiji hadysa düýn-öňňüne çenli iki-ýeke dowam eden hem bolsa, muňa türkmen halkynyň ata-baba