INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (144,1,144,'Žurnalistleri oda salan, 2013-nji ýylyň başlanmagy bilen bolsa tebigatyň gazaby hasam güýjerledi. Orsyýetiň Kurgansk, Swerdlowsk, Ýekatirinburg, Týumen ýaly ýerlerinde şeýle hem Gazagystanyň käbir sebitlerinde edil Injil, Kuran ýaly mukaddes kitaplardaky, adamlaryň azandyklary sebäpli asmandan Allatarapyn iberilýän heläkçilikli hadysalary ýatladyp duran içi meteoritli ýagyş ýagdy, şonuň öň ýany bolsa Sibiriň bir ýerlerinde meteorit gaçdy. 2013-nji ýylyň tomsunda suw joşguny agyr apat bolup Orsyýediň, hususanda onuň Sibir sebitleriniň üstünden suw belasy indi. Amur oblastynda, Blagoweşenskide, Habarowsk ülkesinde, Beribijan ýewreý awtonom oblastynda ýüz beren suw joşgunlary şol ýerleriň ýaşaýjylaryny görlüp-eşidilmedik derejedäki kynçylyklara sezewar etdi. Jaýlaryny tä üçeklerine çenli suw basdy. Tutuş sebit gark aldy. Şol betbagtçylygyň bir ujy baryp Hytaýa ýetdi. Resmi suratda berlen maglumatlara görä, şol ýerlerdäki bolup geçen suw joşgunlary zerarly iki ýarym million adam dürli görnüşlerdäki kynçylyklara uçrapdyr. 24-nji awgusta dilini ýalmandyryp gelýän ot belasy dünýäniň başga bir döwletiniň – Portugaliýanyň başyndan indi. Tutuş ýurt ot içinde galdy. Wenesiýada suw joşdy. Şeýle hem şol senede Genuýada ilkinji gezek gar ýagdy. Ýer ýüzi boýunça kä onda, kä munda ýüz beren şolar ýaly howplyhatarly belaýygerdanlar 2013-nji ýylyň güýzünde hasam möwç aldy. 20-nji oktýabrda güýçli ýagyş ýagyp, Don boýundaky Rostowy sil suwuna gark etdi. 28-nji oktýabrda Günbatar ýewropada dörän güýçli harasat Angliýanyň, Gollandiýanyň üsti bilen Demirgazyk Ýewropa – Daniýa, Belgiýa, Şwesiýa, Fransiýa ýetdi we baryp maňlaýyny Baltika ýakasy ýurtlaryna, Peterburga diredi. Şol hadysany telewideniýe boýunça dünýä ýaýradan žurnalistler ony ―Mukaddes Iudeý‖ diýip, atlandyrdylar. 2013-nji ýylyň 28-nji oktýabrynda Kamçatkadaky elli-altmyş ýyl bäri hiç-hili hereketsiz ýatan ençeme wulkanlaryň bir