INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (145,1,145,'müňdenem gowrak adamyň başyna ýetdi, millionlarça adam dürli görnüşdäki heläkçilikler bilen ýüzbe-ýüz boldy. Ony: ―Hut ahyrzamananyň özi‖ diýip atlandyrdylar. 2013-nji ýylyň noýabr aýynyň başlaryna, hemişe şol döwür gyşy garşylaýan Orsyýetiň günortasynda 11-den 17 gradusa çenli maýyl boldy, baglar miweledi, güller açyldy, baýyrlar ýaşyl maýsalara beslendi. Şol ýylyň 9-njy noýabrynda bolsa Krasnoýarsk ülkesinde ýerleşýän Norilskide Taýmyr ýeli adamlary uly aljyraňňylyga saldy. 18-19-njy noýabrda, Hytaýda henize çenli görlüp-eşidilmedik güýçli gar ýagdy. 19-njy noýabrda, Italiýada ýüz beren suw joşguny ýurduň ilatyny ummasyz heläkçiliklere sezewar etdi. 9-njy dekabrda Finlandiýanyň çäginde güýçli harasat gopdy. 10-njy dekabrda bolsa, Gürjüstan ýurdunda henize çenli görlüpeşidilmedik syrgynly gar ýagdy, ýer doňdy, ýollar sürçek boldy, howa şatlady, halk, hususanda daglyk ýerleriň ýaşaýjylary kynçylyk çekdi. Heläkçilikler ýeke bir ýokarda agzalanlar bilen çäklenmedi. Dünýäniň dürli ýurtlarynda şondan soňam ýagny, 2014-nji ýyla geçilendensoňam, mahal-mahal, onda-munda dowam etdi durdy. Mysal üçin, 214-nji ýylyň 4-nji ýanwarynda, ABŞ-da agyr gar ýagdy we uçursyz aýaz boldy. Garyň galyňlygy 5 metre, aýaz 50 gradusa baryp ýetdi. Müňlerçe awiauçarlar togtadyldy. Germaniýada bolsa şol döwür agaçlar pyntyklady. Lissabonda, Portugaliýada, Beýik Britaniýada güýçli harasat gopdy. Orsyýetiň Amur oblastynda, Ýakudystanda aýaz 50 gradusa ýetdi. 2014-nji ýylyň fewral aýynyň başlarynda, hemişe tutuş gyşy maýylganlykda geçýän Türkmenistanda güýçli aýaz boldy. Onuň demirgazyk welaýaty bolan Daşoguzda aýaz gijelerine 27 gradusa çenli baryp ýetdi. 2014-nji ýylyň 12-nji fewralynda Beýik Britaniýada suw joşguny döredi. Mart aýynyň 28-i güni bolsa Türkmenistanyň paýtagty Aşgabatda 32 gradus yssy bolup, şol günüň ertesi agşam tempuratura nol gradusa çenli aşak düşdi, gar gyrpaklatdy.

