INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (146,1,146,'Bolup geçen heläkçilikli, adaty bolmadyk hadysalaryň bu entegem hemmesi däl. Ýöne, hemmesini sanap oturmaklygyň derwaýyslygam ýok bolsa gerek. Şol hadysalaryň hemmesiniň diýen ýaly fiziki hem himiki häsiýetlerini, ýüze çykmaklarynyň sebäplerini, tebigy aýratynlyklaryny dünýä alymlary ylmy taýdan, hertaraplaýyn öwrendiler, özleriçe baha berdiler, halk köpçüliginiň öňünde çykyşlar etdiler, ol zatlaryň ahyrzaman bilen hiç hili arabaglanyşygynyň ýokdugyny düşündirdiler. Adamzada ýenede şolar ýaly köp-köp hadysalaryň garaşýandygyny aýtdylar. Elbetde, olaryň aýdanlary bilen ylalaşmazlyga hakymyz ýok, esassyz zatlaryň aýdylmanygna-da ynanýarys. Ýöne, ylym bilen dini taglymatlaryň, tehnika blen ruhy güýjüň, akyl-paýhasyň aýakdaş gitmelidiklerine görä, 2013-ni ýylda ýüz beren şol hadysalary ýeke bir ylmy-tehniki tarapdan däl-de, eýsem gadymy, mukaddes dini kitaplarda berilýän maglumatlar, pygamberleriň aýdanlary bilen deňeşdirmek arkaly öwrenmek has netijeli bolardy. 1867-1960-njy ýyllarda Türkiýede ýaşap geçen Seýit Nurly bu dogrusynda şeýle diýýär: ―Wyždanyň yşygy dini ylymlardadyr, aklyň nury bolsa takyk ylymlardadyr. Şol ikisiniň birleşmesinden hakykat ýüze çykýar. Olar biri-birinden aýrylan wagty birinjisinden öz bilýän zadyndan başgasyny unamazlyk, ikinjisinden bolsa hile we şühbe dörär‖. Diýmek ylmy babatdaky hakyky ösüşlere, tebigy hadysalara, hatda syýasy üýtgeşmelere hem diňe şol ikisini bilelikde öwrenmek arkaly göz ýetirip bolar. Munuň hakykatdan-da şeýledigini tassyklaýan alymlar bu gün ýer ýüzünde bir ýa iki däl. Şu nukdaý nazardan seretseň, 2013-nji ýyldaky bolup geçen heläkçilikler žurnalistleriň bir ýyl öň ýanjap geçen ahyrzamanalary bilen dälde, Kurany Kerim, Injil, Töwrat ýaly mukaddes dini kitaplarda beýan edilen Nuhuň tupany we her gezek adamlaryň aglabasynyň azyp, Hudaýy unudan mahallary, olary ýok etmek üçin asmandan Allatarapyn inderilýän arassalaýyş çär