INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (165,1,165,'Ýehowa – jöhütçe, Taňry – gadymy türki halklarynyň (Gök taňryçylyk) dilinde we ş.m. Ol älem giňişliginiň islendik künjegindäki bolup geçen, bolup duran we boljak zatlary dürbüsi bolmasa-da görýär, aýdylan, aýdylýan we aýdyljak sözleri, sesleri telefony bolmasa-da eşidýär. Permanam berýär, golam çekýär, möhürem basýar. Onda-da her kimiň, her bir zadyň ed-dil ýazzy maňlaýyna basýar. Onuň mümkinçilikleriniň çägi ýok. Ol hökmürowan. Jümle-jahanyň eýesi. Bar baýlyk şonuňky. Çünki, Ol Ýaradyjy. Hudaý! Ol göze görünmezden özüniň bardygyny bildirýär. Ähli zatlardadygyny duýdurýär. Ony diňe şeýtanyň alyna gidenler görüp we duýup bilmeýärler. Göze görünmeýän güýjüň, hatda göze görünmeýän dünýäniň hem bardygy Injilde aýdylýar. ―Başda Hudaý göze görünmeýän dünýäni – perişdeler dünýäsini ýaratdy‖ diýilýär. Perişdeler Hudaý bilen adamlaryň arasynda aragatnaşykçynyň, roluny oýnaýarlar. Ýöne, Lut pygamber bilen bagly tymsaldan görnüşi ýaly, gerek bolan wagty Hudaýyň olary adam sypatyna salyp ýere ýollan gezeklerem bolupdyr. Bu hem asman bilen zeminiň, tebigat bilen adamlaryň göze görünýän we görünmeýän dünýäleriň bir bitewidikleriniň alamatydyr. Göze görünmeýän dünýä we perişdeler bilen bagly düşünje yslam taglymatynda hem bar. Ýagny, her adamyň her çigninde bir perişde oturarmyşyn we olaryň biri onuň edýän günälerini, beýlekisi bolsa gazanýan sogaplaryny ýazýarmyşyn, soň olar şol maglumatlary Hudaýa eltip berýärlermişin. Hut şol maglumatlar arkaly Hudaý kyýamat güni adamlara baha kesjekmişin. Bu bolsa adamzady ruhy taýdan päk, arassa hem ahlakly terbiýelemegiň iň güýçli görnüşleriniň biridir. Göze görünmeýän güýjüň hakykatdan-da bardygyny iki taglymaty hem degşirip öwrenýän alymlar şeýleräk düşündirýärler: ―Tok biziň gözümize görnenok, emma ol bütin dünýäni herekete getirip dur. Telewideniýäni, radiony, el telefonyny, interneti hem şoňa mysal edip görkezse bolar. Olarda görkezilýän z