INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (166,1,166,'Söýgem göze görünmeýär, ýöne adamzat onsuz ýaşap bilmeýär. Onsuz çyraglar ýanmaýar. Ol guşlary agladýar, gurtlary eňredýär. Daglary titresýär. Ýöne, onuň nämedigini welin Biribaryň özünden başga bilýän ýok. Ine şol göze görünmeýän, ýöne pelegi gökde gerdana salyp, ýerde halklary her köýe salyp ýören ägirt uly güýç, söýgi hem Hudaýdyr. Perişdeleriň ynsan bilen Hudaýyň arasyndaky aragatnaşykçy, maglumat ýetiriji diýlip bilinmeginiň aňyrsynda-da kosmos bilen adamlary baglanyşdyryp duran äpet bir energetiki güýjüň bardygy hakyndaky hakykat ýatyr. Ýöne, älem içre bar zady berkarar edenem bolsa, Hudaý köp zady oýlap, gözläp tapmaklygy, döretmekligi adamzadyň özüne goýupdyr. Özi Ýaradyjy bolsa, oňa döredijilik ukybyny beripdir. Çünki, Ol owalebeetde ynsany özüne kybapdaş ýaradypdyr. Ine, hut şonuň üçinem, adamzat hemişe Hudaýyň derejesine ymtylmalydyr, şeýtanyň derejesine çenli pese düşmeli däldir. Adamzat umuman, şeýle hem etdi. Allanyň buýrugyna eýerip ol köp zatlary döretdi. Köp zatlary oýlap tapdy. Arşa aralaşdy. Zeminiň göwsünden gara hem mawy altyn çogdurdy. Akylly-başly hereket edip gidiberse, ol entegem özüne bu güne çenli mälim boomadyk köp-köp zatlaryň üstüni açar. Hatda, göze görünmeýän dünýäniň efir tolkunlaryny tapyp, onuň bilen aragatnaşyga giraýmegem, garyndaşlyk açaýmagam ahmal. Hudaý asylam öz bendeleriniň bu günki ýaly ölüm getiriji kyýamaty golaýladygyjy, dünýäni weýran ediji, hatda göze görünmeýän dünýäniňem gözüni ajy tüssä gapdyryjy ýaraglary, därileri, zäher-zakgunlary ýasamaklaryny däl-de, dünýäniň şol bir arassalygyny gorap saklaýjy enjamlary oýlap tapmaklaryny, şeýtana tarap däl-de, mukaddes zatlaryň mukaddesligini, owalebetde öz beren ruhy hem beden päkliklerini kyýamat güni şol bir terligi bilen özüne gowşurmaklaryny isläpdi. Hut şonuň üçinem Ol adam ata bilen How enäni uçmahdan kowanda: ―Ruhy hem beden taýdan başky päklik derejäňize ýeten, şeýtand