INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (175,1,175,'Allatarapyn iberilen heläkçiliklerden umuman alanyňda şeýleräk netije çykarmak bolar. Çünki, Adam ata bilen How eneden bäri arassalaýyş çärelerini näçe gezek gaýtalan hem bolsa, kyýamatyň alamatlaryny artyk gaýtalamaz. Şundan soň duýduryş bermez. Şonuň üçinem, biziň bu zatlardan iňňän eserdeňlik bilen akylly-başly baş alyp çykmagymyz gerek. Ine, şuňa welin, Allatagalla maý berer/ dogup-döräli bäri adamzat ylym-tehnika arkaly özi üçin ýeke bir maddy oňaýlyklara däl, eýsem, sanap çykardan kän, çözmesi kyn, öz janyna dalaş ediji köp-köp kynçylykly meseleler, betbagtçylyklar hem döretdi. Ol henizem şeýdip gidip otyr. Muny onuň özem bilýär. Duýýar. Şol nogsanlyklary aradan aýyrmak üçin hereketem edýär, ýöne, ol şol meseleleri ýene-de maddy serişdeler arkaly çözjek bolýar we özi üçin howply bolan belaýygerdanlary täze-täze tapgyrlaryny döredýär. Bu bolsa ony ýene-de Baky ýoklyga tarap itekleýär. Sebäbi ol zatlaryň aňyrsynda şeýtan dur. Öňünde keserip ýatan şol agyr hem kyn meseleleri diňe ruhy serişdeler – iüki päklik, arassalanyşlar arkaly, eden günäleri üçin Hudaýyň öňünde toba etmek mundan buýana diňe Allanyň arassa we göni ýoly bilen gitmek arkaly adamzat ahyrzamanadan halas bolup biler. Hudaýyň öz islegem şol. Çünki, Ol geçirimli. Sözümiziň soňunda bolsa, alym Bertran Rasseliň şu sözlerini getirmek isleýärin: ―ylym we tehnika häzir sürüjilerinden jyda düşen tanklaryň toplumy ýaly köre-körlük, paýhassyzlyk bilen, belli bir maksatsyz halda öňe tarap okdurylyp barýar‖. 2014ý. Aşgabat

