INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (178,1,178,'Bu zatlary diýmek bilen biz, ýeke-ýeke sanap oturmanyňda-da, şu halkyňam köçä çykara, goh turuzara bahanasy ýok däl, problemalaram az däl, ýa käbir ýoldaşlaryň aýdyşy ýaly ol şeýle bir susam däl, ol ýöne ähli zada syňragyndan sim geçirilen gurduň möjek çydamlylygy bilen çydap ýör, sabyr — takatlylygyň nusgasyny görkezip ýör, diýjek bolýarys. Asyl ol başda-da öz çydamlylygynyň nazara alynjakdygyna, göwün-islegleriniň gohsuz-galmagalsyz amala aşyryljakdygyna bil baglapdy. Ýöne şol çydamlylyk, sabyr — takatlylyk sylandymy? Äsgerildimi? Respublikanyň ýolbaşçylary onuň kysmata kaýyllygyna sarpa goýup berç bolup ýatan arzuw — isleglerini dawa — jenjelsiz, öz wagtynda ýerine ýetirmek uçin alada etdilermi? Ine şu zatlary aýyl-saýyl etmezden, Turkmenistanda üýtgedip gurmagyň gidişi barada pikir ýöretmek mümkin daldir. Geliň, gowusy faktlara ýüzleneliň. Öňi bilen dil meselesi barada. Tas, bir ýyla çeken dil göreşi, — Turkmenistan ССР-iniň ýolbaşçylarynyň, esasanam ТКП МК-yň birinji sekretary ýoldaş S.Nyýazowyň syýasy biografiýasyny hiç haçanam owadan harplar bilen bezemese gerek. Sebabi ol bu meselede halkynyň agraslygyndan ýalňyş peýdalandy. Şeýtsem merkezi ýolbaşçylara gowy görünerin diýen niýet bilen, başdanaýak, türkmen diline döwlet dili hukugynyň berilmegine garşy gitdi. Ähli respublikalarda ýerli dile döwlet dili hukugy berilenden soň, esasanam, her bir respublikanyň öz diliniň döwlet dili bolaýmalydygy baradaky Bütinsoýuz dil kanuny çykandan soň bolsa ur-tut, öňki pozisiýasyndan dändi we düýn — öňňünem respublikan radionyň, telewideniýänyň, gazet — jurnallaryň redaksiýalaryndan içinde ''''status'''' sözi bar bolan makalalary aýyrdyp, redaktorlary sykajaga salyp, dil ugrunda göreşip ýörenleri ''''bulagaý'''' atlandyryp ýörendigine garamanan, türkmen diline hem döwlet dili hukugynyň beriljekdigi barada çykyşlar edip ugrady. Şeýdibem ol özüniň prinsipial, ýiti syýasatçy däl