INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (181,1,181,'eserini sile aldyran wagty başyndan geçiren elhenç duýgularyny başyndan geçirýär. SSSR-iň köp milletli ýurtdygyna garamanan, merkezi telewideniýe boýunça gepleşikler berlende-de, kinofilmlar, konsertler görkezilende– de,wideokasetalar ýaýradylanda-da ,her sebitiň öz milli aýratynlyklary nazara alynmaýar. Üýtgedip gurmak döwründen türkmen halky şu meselede-de gaty kän zatlara garaşdy.Ýagdaý welin bilşiňiz ýaly öňküsindenem ýaramazlaşdy. Biz gündogar adamy. Biziň hut,özümize mahsus bolan edimgoýumlarymyz, däp dessurymyz bar. Utanç-haýa babatda-da öz düşünjämiz, ýörelgämiz bar. Şol durşumyza-da galasymyz gelýär.Biz islendik halkdan öz ruhumyza golaý bolan häsiýeti kabul edip bileres. Medeniýetindenem sungatyndanam geregimizi alarys.Biziň bilen bir toprakda ýaşaýan halklaryňa,biziň dessurlarymyzy öwrenmänlerinde-de, hiç bolman-da sylamaklaryny welin isleýäris. Elbetde, biz klublarda görkezilýän şerimsiz kinolara gitmänem bilýäs.Ýöne,öýde,ata-enelerimiz, ogul-gyzlarymyz bilen bir jaýda telewizor görüp otyrkak, ekranda ogşaşyp,ýalaşyp her-hili wejeralyklara meşgul bolşup başlaýan aýaldyr-erkeleri görenimizde, biri-birimizden uýalmakdan ýana bir ýere girip bilemizok. Soňam telim günläp biri-birimiziň ýüzümize seretmägede utanyp ýörüs. Ine, şu-da biziň halkymyzyň ahlak terliginiň, inçe duýgurdylygynyň sylanmaýandygynyň, oňa aýratyn halk hökmünde hormat goýulmandygynyň alamatydyr. Gören gözleriň aýtmaklaryna görä, hatda Amerikada hem özüne hormat goýýan maşgalalaryň telewizorlarynda şeýle wejeralyklar görkezilmeýärmişin. Aýşy-aşratyň waspy ýaňakdan posa almakdan aňry geçmeýärmişin.Ady arşa çykan wejeralyklary görkezýän kanallar diňe şol zatlary göwni küýseýänler üçin kabel arkaly görkezilýärmişin. Şol kanallary görmek üçin bolsa jübüňden ummasyz pul tölemelimişin. Tertipli, düzgünli ýurtlarda ähli zat ine, şular ýalyrak edilip gurnalypdyr. Bu meseläniň ýeke bir bizi däl, soýuzy