INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (189,1,189,'Şular ýaly jyg-ba–jygly pursat gelende halkyň aňynda beýle düşünjüni döretmegem, ýaýratmagam nädogrudyr. Gorkulydyr. Ejizlikdir. Ençeme ýyl bäri nirä diýseň sessiz-üýnsiz yzyna düşüp ýören halkyň sabyr-takatlygyny synap gidip otyrmaklygy gereginden artyk dowam etdirmekdir. Şu ýerde bir tymsal ýadyňa düşýär.Ýagny,bir wagtlar bir obada bäş sany ýetim oglan ýaşapdyr.Bir günem goňşylary olara dadymlyk bir okara aş getirip beripdir.Doganlar maslahatlaşypdyrlar-da , gezek-gezegine adam başyna dokuz çemçeden içmeşek edipdirler.Öňürti ulusy başlapdyr.Ýöne ol ýaňy bir sekiz çemçe içenden aş gutarypdyr.Muny görüp kiçileri: ''''dat-bidat, datman galdygaý''''diýşip aglaşmaga başlapdyrlar.Şol wagt ulularam :''''Dat,menem içmelije dokuz çemçämiň hemmesini içip bilmedimaý.''''diýip,jigilerindenem beter aglap başlapdyr. Biziňkem bu gün ana şoňa barýar.Bu gün indi sekiz çemçe içenem aglaýar,düýbinden datmadygam aglaýar. Eýsem onlarça ýyl bäri biziň gaz turbalarymyzyň içinden akyp gidýän akym ugry merkezden – Orta Aziýa tarapmy ýa Orta Aziýadan –merkeze tarapmy? Nebit daşaýan ýük eşelonlary Orta Aziýadan –merkeze boş gidip,şol ýerden yzlaryna dolyp daşyp gaýtýalarmy ýa merkezden Orta Aziýa boş gidip,yzlaryna doly gelýälermi?/ Bu barada doly bilerin öýütseň seret: T.Gutlyýew. ''''Hasaply dost uzaga gider'''' Ýaş kommunist.gaz. 24.7.1990./ Bizi ähli zadymyzdan mahrum eden gymmatbahaly pagtalar wagon-wagon bolup, deger-degmezine Orta Aziýadan merkeze tarap gaýdýarmy ýa merkezden Orta Aziýa tarap? Goý, bize ―ýal ýagysydyr‖ öýden her bir adam bilsin, ki: ýagny, Türkmenistan bir ýylda 91 mlrd. kub.m. gaz öndürýandir. /Sibirden soň soýuz boýunça ikinji ýerde durýar. Emma, Moskwada köp adamdan sorap görýan welin, Türkmenistandan-da gaz öndürilýaninem bilenoklar./ Şol gaz häzirki nyrh boýunça 7 mlrd. dollara barabar. Bir dollaryň bahasam gara bazarda orta hasap bilen 20 manat diýsek, türkmen gaz