INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (199,1,199,'Türkmen han – begleri, işan – mollalary uly – uly tutumarda beýik söweşleriň öň ýanynda edilýän maslahat – mejlislere garamaýak halkyň wekillerini hem çekmek bilen, heniz adyny – soruny eşitmedik zatlarynyň – demokratiýanyň iň ýokary nusgasyny görkezipdirler. Mysal üçin, 1978-nji ýylda, general Lomakiniň ýolbaşçylygynda, rus goşunlarynyň ilkinji gezek Ahal topragyna goşun çekip gelen wagty, uruş hereketlerine başlamazdan öň, ahal tekeleriniň geçiren geňeş – maslahatynda han – begleriň, işan – mollalaryň we beýlekileriň uruşmak baradaky eden teklipleriniň tersine syçmazlardan Hanmämmet atalyk bilen beglerden Orazmämmet han ikisi san taýdan azdyklaryny,ýarag ýagdaýlarynyň ýaramazdygyny, şoňa görä – de agyr netijeleriň bolup biljekdigini göz öňüne tutup, ruslar bilen uruşmazlygy ündeýärler. Maslahata ýygnananlaryň içinde bu ikisine dönük, haýyn, orslara satylan diýenlerem bolupdyr. Emma maslahaty alyp baryjy ýaşulylar olara: ―Hanmämmet bilen Orazmämmet ikisi ak ýürekden öz pikirlerini aýtdylar. Ätiýaçlylyk hem seresaplylyk gowy zat, diýdiler. Hemme kişini parasatlylyga, pähim-paýhasa çagyrdylar. Her bir adama, onda – da Orazmämmet han bilen Atalyk ýaly atly abraýly adamlara öz pikirini, pähim – paýhasyny erkana aýtmaga mümkinçilik bermek gerek. Şeýle edilmejek bolsa onda maslahat nämä gerekdi‖ diýýärler. Şondan soň Hanmämmet atalyk bilen Orazmämmet han ikisem: ― Biz öz pikirimizi aýtdyk. Namart, gorkak däldigimizi bolsa söweş güni subut ederis, sözümiz geçmedi diýip gaýra durmarys. Siz ölmäni başarsaňyz – biz ölmäni başararys‖ diýýipdirler. Hemmeden öňürti gurhandan ant içipdir we tä, rus goşunlary ýeňlişe sezewar bolup yzlaryna dönýänçäler uly il bilen bilelikde mert durup söweşipdir. Şol geňeşde aksakgallar belli bir netijä gelip bilmän, meseläni halkyň ygtyýaryna hödürlemeli, özem köpçüligiň erki azlyk üçin hökman bolmaly diýen netijä gelipdir. Köp müň adam gatnaşan şo