INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (200,1,200,'Şol urşa-da, ikinji urşa-da garyp – pukaralar bilen bilelikde han – begler, işan – mollalar hem gatnaşýarlar. Nurberdi hanyň ogly Berdimyrat han hemişe urşuň gür – gümmesinde bolýar. Uruşa gös- göni ýolbaşçylyk edýär we ikinji uruşda mertlerçe wepat bolýar. Uruş gutarandan soň Marydan gaýdyp gelen Nurberdi han oglunyň ölenini eşidip, bu ýagdaýa özüniň begenýändigini aýdýar. ― Uly il üçin şeýle agyr günde men pida çekmedik bolsam, meniň üçin masgaraçylyk bolardy‖ diýýär. Ine, bu wakany bolsa şu günki goşun gullygyna alnyşyklar bilen, esasanam owgan urşuna kim-kimleriň çagasynyň alnyp, kimiňkileriň alynmadygy bilen deňeşdirip görüň. Şonda köne, türkmen demokratiýasynyň set-müň kanunlar bilen berkidilýän, ýalan demokratiýalardan näçe esse beýik hem kämil ekendigine göz ýetirersiňiz. Ýokarda getirilen tymsallar demokratiýanyň iň bir tebigy nusgasydyr. Türkmen halkyny demokratiýanyň nämediginem bilmeýän halk hasap edýän birnäçe ösen döwletler we öz içimizdäki kemsowatlar üçin görümdir, göreldedir. Demokratiýanyň şular ýaly tebygy görnüşlerini Mary tekeleriniň hany Gowşut hanyň, salyrlary iň soňky gezek Sarahsa ýygnan Teke hanyň, Demirgazyk ýomutlarynyň hany Jüneýit hanyň, Kaspi ýakasynda ýerleşen ýomutlarynyň hany Kyýat hanyň we başga ençeme han begleriň dürli döwürlerde geçiren taryhy teşwüşleriniň mysalynda hem görmek bolýar. Şeýle mysallary gadymky gerçeklerimiziň – Oguz hanyň, Gorkut atanyň, Baýandyr hanyň, Salyr sazanyň, Jygaly begiň, Görogly begiň asylly hereketlerinde hem görmek bolýar. Şonuň üçinem, şu halk demokratiýa taýýar dal, diýmek hebesdir. Halk demokratiýa hemişede taýýardyr. Demokratiýa elmydama eziji synp taýýar däl ýagdaýda durýandyr. Çünki, bu onuň bähbitlerine ters gelýär. Hökmürowanlyk edip, diýdimzorluga daýanyp demokratiýany gysyp, syýasy işjeňliginii her hili ýollar bilen basyp, halky köçä iterýänem hut, şolardyr. Ikitaraplaýyn ylalaşykly, sypaýaçyl