INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (217,1,217,'Ýerli däl halklar welin türmen dilini öňem bilenokdylar, ýerli dile döwlet dili hukugyny bermeseň, döwlet edaralaryny millileşdirmeseň, mundan bu ýana-da bilmezler. Türkmen diline döwlet dili hukugyny bermeklik – türkmen dilini rus diliniň garşysyna goýmaklyk ýa respublikanyň içinde ýaşaýan beýleki halklaryň duýgusyny kemsitmek däldir. Bu düşünje nädogrydyr. Gaýtam ýerli halkyň öz ene diline döwlet dili hukugyny bermezlik, ýerli halkyň guýgusyny kemsitmekdir. Ony milli hukugyndan we buýsanjyndan mahrum etmakdir. Türkmenleriň içinde henize çenli kemsidilen halk ýokdur. Bardygeldi kemsidilen bolsa-da, onda şol halk ýerli halkyň özüdir. O-da öňi bilen dil zerarlydyr. Howwa, dil zerarly biz köp kemsindik. Köp kösendik. Köp horlandyk. Emma şonda-da syr bildirmedik. Çydadyk. Pasportlarymyza atalarymyzyň, enelerimiziň ady, öz adymyz ýoýulyp ýazylanda-da, köne galalarymyzyň, şäherlerimiziň, beýik-beýik şahyrlarymyzyň atlary düýbünden ýalňyş tutulan-da, garry-gurtlarymyz, gara zähmetden başga zady bilmeýän sada daýhanlarymyz şowhunly şäherlerimize gelip dükandan-däkana, uly-uly edaralara, arz jaýlaryna aýlanaaýlana „adam dilinde― gürläp bilmeýändikleri sebäpli ýüzleri alnyp, it ýaly dalanyp kowulanlaryn-da , öz ilinde özlerini ýat saýyşyp, ýaýdanşyp ýörüşlerini gözümiz bilen görenimizde-de, birinji klasdan tä onunja çenli pagtanyň içinden çykman, pestisit ýuwdup gelen çagajyklarymyz öz ene dillerinde bilbil ýaly saýrap durkalaram rus diliniň diktantyndan ýykylyp, göwün söýen kärine ýetibilmän köýüpler gidenlerinde-de, okuw jaýlarynda türkmençe okudandygymyz üçin partiýanyň şäher komitetine çagyrylyp, hamala jenaýat eden ýaly : „Dagy-duwwara şular ýaly iş edäýseň gowulyga garaşma― diýen ýaly sowukdan sowuk sözleri eşdip, ýeňsämize käýenç ýelmedip gaýdan gezeklerimizde-de, içinde türkmençe düşünýän ýekeje adamyňam ýokdugy zerarly, şäher edaralaryna türkmençe ýazylan arzalarymyzy,