INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (226,1,226,'Dogrusyny aýdalyň, käbir köçäniň, ýa okuw jaýynyň adyny üýtgedeniň bilen, dil meselesini çözdügiň bolanok. Olar öňem bolaýmaly zatlar. Ertir ony etmekçi, birigün muny etmekçi diýip, agzyňda aş gatyklanyň bilenem iş bitenok. Esasy mesele kanuny döwlet möçberinde ýerine ýetirmekden, döwlet we aragatnaşyk edaralarynda aeroflot we demir ýol kassalarynda, söwda nokatlarynda, poliklinikalarda, keselhanalarda, derManhanalarda, okuw jaýlarynda türkmen diliniň gürrüňsiz rowaçlanmagyny ýola goýmak dan ybarat. Şu meseleler babatda goýberilýän käbir nogsanlyklary duran ýerinde barlap görmek mümkin. Mysal üçin, aeroflot agentliginiň sorag-jogap býurosyna jaň etseň, türkmençe jogap berýärler. Bu ýagdaý ýaşaýyş jaý uprawleniýýeleriniň welin hersinde we her günde birhili. 09-a jaň etseň, türkmençe jogap berenoklar . ―Näme, türkmençe jogap berip bileňzokmy?‖ diýseň: ―Duruň onda, adam tapyp geleýin‖ diýýärler-de, trubkany taşlap, nirädir bir ýaňa ylgaşlap gidýärler. Dil kanunynyň ―depme halal‖ edilýän ýeriniň ýene birem samolýotyň üstüdir. Ugrajak wagtyň stýuardessalaryň biri yrym üçin, tekste seredip, radio boýunça, patdyk-sutdyk bäş-on agyz türkmençe sözlän bolar. Gürrüňiň yzy tä reýs gutarýança rusça gider. Düşjek wagtyňyzam: ―unus berib diňleniňiz uçun sag bolun...‖ diýer, wessalam! Sen bolsaň öz uçaryňda uçup barýarkaň, öz ene diliňde gürlenilýändigine buýsanmakdan geçen, gaýtam onuň şeýle äsgermezlik bilen hary-zar edilşine utanmakdan ýaňa çym-gyzyl bolup oturansyň. Ministrliklerden, pudaklaýyn dolandyryş edaralaryndan ýerlere iberilýän hatlaram edil öňküleri ýaly rus dilinde iberilýär. Bir üýtgän zat – blankanyň ýokary burçunda rusçasyny çep tarapynda ―yrym üçin‖ iberijiniň adresi türkmençe hem çap edilen. Bolany! Ýokary okuw jaýlarynda hem dil kanunynyň ýerine ýetirilşi juda ýabygorly. Şu ýagdaýy dert-azar türkmençe okuw kitabynyň ýokdugy, kadrlaryň ýetmezçilik edýändigi bilen d