INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (229,1,229,'Ine, saňa zerurlyk! Ine, saňa mümkinçilik! Ine, saňa adam barada alada. Diňe: ―Dat, biziň dilimizi öwrenenoklar‖ diýip gygyryp oturmagam gerek däl ekeni. Gelen adamyň öňünde şert goýmaly ekeni. Zerurlyk, maddy mümkinçilik döretmeli ekeni. Belki, başga-başga çärelerem agtarsa bolar. Häzir welin biz öz aramyzda ýaşap ýören saýry garyndaşlarymyzdan gury talapdan başga edibilýän zadymyz ýok. Elbetde, olaram birbada öňküje gelýän, endigan ýörelgelerinden çykmany kyn görýändirler. Şonuň üçinem, häzirki pursatda köp babatda halkyň janköýer ogulgyzlaryna bil baglaýmak galýar. Ýagny, Ümür Eseniň mekdeplerde ―Edep‖ sapagyny girizişi we şol sapak üçin okuw kitabyny ýazmaklygy öz boýnuna alşy, Geldi Kärizowyň ahal-teke atlaryna hossar çykyşy ýaly, her kimiň ýerliýerden goluny çyzgap işe girişibermegi gerek. ―Alma biş, agzyma düş‖ diýip ýatanyňdan peýda ýok. Okuw kitaplary ýok bolsa, şol ugurdan işleýän merdana ýigitlerimizdir gyzlarymyzyň, agalarymyzdyr inilerimiziň hersiniň öz okadýan okuw kitabyny döwtalaplyk bilen terjime edibermekleri, çap edilmegini talap edip, taýyn golýazmalaryny ýolbaşçylayň öňünde gütüledipgütüledip goýbermekleri gerek. Aramyzda ýaşaýan gaýry gardaşlarymyzyňam beýdip bize gereginden artyk ýanjatdyrjak bolup durman biziň bilen hakykatdanam dogandyklaryny indiberin boýun almaklary, öňi bilen özlerine bähbitli bolan dil meselesiniň çözgüdine hut özleriniň döwtalaplyk bilen goşulyşybermekleri gerek. Çünki, birek-biregiň diline düşünilmese dogan bolup bolmaýar. Onsoňam bu döwür bizden gahrymançylygy, galkynyşy talap edýän döwür. Garamaýagyň ýolbaşçydan, ýolbaşçynyň garamaýakdan goltga garaşýan döwri. Ähli dawa-jenjellerden parasatlylyk bilen sowlup geçip, ähli derwaýyslyklary parahatçylykly ýol bilen çözmekligiň usullaryny agtarmaklygyň döwri. Ýöne, barybir ýokardan yşarat bolmasa, garamaýaga kyn bolýar. Kähalatlarda bolsa onuň hereketlerine ters düşünilýär. ―