INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (231,1,231,'Türkmençe ýazdyklary şol. Şolar ýaly başdansowma ýazgylary ýerli harytlaryň nyrhnamalarynda-da, ýarlyklarda-da, çüýşeleriň böwrüne ýelmenýän hatlarda-da, dürli bildirişlerdir afişalarda-da görmek bolýar. Eger-de, ýokarda belläp geçişimiz ýaly, dil baradaky kanunda obýektleri iki dilde ýazmaly diýip görkezilen bolsa, haýsydyr bir harp hem rus grafikasynda ýok bolsa, onda bu ýagdaý bilen ylalaşsa-da bolardy. Emma bu ýerde ýagdaý düýbünden başgaça. Bu ýerde diňe öz hak eýesi tarapyndan sylanmaýan dile keseden äsgermezçilik etmek endigi bar. Çünki, şu agzalan zatlary redaktirläp oturan redaksiýa ýa kommisiýa ýok. Bar bolaýanda-da şol redaksiýanyň ýa komissiýanyň agzalarynyň döwlet dilini oňly bilýän adamlar däldigi görnüp dur. Dogry, ýaňy-ýakynda TSSR-iň Prezidentiniň 1991-nji ýylyň 1-nji oktýabrynda çykaran 410-njy kararyna goşundy hökmünde kärhanalaryň, edaralaryň, guramalaryň, okuw jaýlarynyň we beýleki obýektleriň atlaryny hem-de olary üýtgetmek boýunça Türkmenistan SSR-niň Prezidenti S.A.Nyýazowyň karary çap edildi. Komissiýa-da düzüldi. Ýöne, bu komissiýa hem köçe atlarynyň ýa graždanlaryň pasportlaryna öz atlarynyň, adresleriniň dürs ýa nädürs ýazylyşyna gözegçilik etmez. Bu onuň funksiýasyna-da girmeýär. Ol komissiýa nirä nähili at dakmaly, nämäniň adyny üýtgetmeli, ine, şo zatlar bilen meşgul bolýar. Köçe atlaryny, edara atlaryny, dokumentleri dürs ýazmak boýunça bolsa düýbünden başga bir komissiýa has dogrusy, redaksiýa gerek. Ýa-da şuny goşmaça hak töläp haýsydyr bir redaksiýanyň, dil institutynyň ýa-da haýsydyr bir janköýeriň üstüne atmak gerek. Garaz, gözegçiligem, jogapkärçiligem güýçlendirmek gerek. Ýogsam öz adymyzam, atalarymyzyň adam, köçedir şäherlerimiziň adam öňküsi ýaly şo-ol, üýtgär gider oturar. ―Guly‖ bolsaň-a, ―Kuli‖ bolarsyň, ―Berdi‖ bolsaňam, ―Berdy‖ bolarsyň. ―Myrat‖ bolsaň bolsanym hökmany suratda ―Murad‖ bolarsyň. ―Grişa‖ türkmen ady bolan bo