INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (232,1,232,'ýere baryp iliň köçe şäher atlaryny, adam atlaryny özümizçe aýtgedip ýazamzok. Ýa-da pasportlarynyň bir gapdalyna türkmençe wariantyny ýazamzok. Rus atlarynyň-a ýekejesiniňem üýtgedilen görnüşini türkmen dilinden tapmarsyňaz. Biziň bar ýetip bilmeýän zadymyz öz öýümizde, öz atlarymyzyň üýtgewsiz tutulmagy. Köne keseklerimiziň, oba, şäher atlarymyzyň, gerçeklerimiziň atlarynyň dogry ýazylmagy. Atalarymyzyň adynyň soňundaky‖...ew‖ goşulmasynam bize soň ýelmenendigi barada şu çaka çenli metbugatda-da, dürli ýygnanyşyklarda-da köp gaýtalandy. Onda-da diňe rus gramatikasyna degişli goşulmadygy, ―Çeý?‖ diýen soraga jogap bolýandygy düşündirildi. /‖Çeý ty? – Kimiň ogly? ―Iwanow‖ – Iwanyň ogly/. Hakykatda welin biz Pylany Pylanyýew däl-de, Pylany Pylany ogly bolmalydyk. Şeýle zorluga biziň ata-baba atlarymyz araplar döwründe-de sezewar bolupdyr. Ýagny: ―...din‖, ―...ed-din‖, ―...as‖, ―...al‖ goşulmalary. Jelale-eddin, as-Suly, al-Faraby we ş.m./ Asyrlara çeken agyr labyryň astyndan biz şu gün çykyp bilmesek, hiç haçanam çykmarys. Ýöne, ―...ow‖, ―...ew‖, ―...owiç‖, ―...ewiç‖, ―...owna‖, ―...ewna‖ ýaly goşulmalardan halas bolarlyk çykalga Dil baradaky kanunda görkezilen. Şeýle-de bolsa ony amala aşyrmakda halk uly kösençlik çekýär. Atlary üýtgedilýän köçeleriň ýaşaýjylary pasportlarynda adreslerini üýtgetmek üçin hat-petek dolduran mahallary köçe adynyň türkmençe wariantyny ýazsalar hem /mysal üçin. B.Garryýew köçesi/, pasportlaryny elerine alanlaryndan soň ol ýere üýtgedilip, rusça ýazylandygyny /B.Karryýew/, görüp galýarlar. Ýa-da öňki ―Lemkulow‖ köçesini alyp görüň. Onuň adyny ―Keýmir kör‖ diýip üýtgetdiler . emma onuň ýedi sany ýolaýyrdynyň /proýezdiniň/ welin henizem öňki durşy. Göräýmäge ownuk ýaly bolup görünýän şu zatlaryň barysy bilelikde alanyňda bize: her ýan ýatsaňyzam öňki-öňkülik bolar, üýtgän zat bolmaz, onuň üçin arrygyňyzam gynap oturmaň, diýildigi bolýar. Galyb