INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (234,1,234,'Has irrkiräk döwürde ýaşap geçen başga bir gerçegiň dil baradaky ýürek nalasyny eşidesiňiz gelýärmi? Baş üstüne:

