INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (235,1,235,'henizem peşmek ýaly şemal haýsy tarapa öwüssse şol tarapa eňip gidip oturşymyz. Elbetde, dil näçe-de bolsa öwrenibermeli. Ol adama artykmaçlyk berýär. Ýöne, özüňkini oňa horlatdyrmaly däl. Gerşinden basdyrmaly däl. Biziň esasy betbagtçylygymyzyň ýene birem – heniz-henizlerem diňe rus dilini bilýän adamlar ýolbaşçy bolup bilýändir diýen düşünjeden saplanyp bilmeýändigimizdir. Türkmen diliniňem diňe bir respublikanyň içinde kökerilip goýaýmaly ikinji derejeli dil däl-de, edil rus, iňlis, pereň, ispan, arap dilleri ýaly, ýer ýüzüniň ähli dilleri bilen deň-derejeli, deň hukukly dilleriň biridigine, islendik döwlet bilen terjimeçi arklay aragatnaşyk saklamaga, hut, öz ene dilimiz arkaly gepleşikler geçirmäge ygtyýarymyzyň bardygyna akyl ýetirip bilmeýänligimizdir. Gepiň gerdişine görä aýtsak, türkmen diliniň üstüne abanan ―howp‖ dürli döwürlerde rus diliniň üstünede abandy. Protopop Awwakumyň: ―...ruslar öz watanynda rus dilinde gürlemelidirler‖ diýip, Iwan Grozna ýazan hatyny ýadyňyza salyň. Çünki şol döwürlerde Orsyýetiň iň bir medeniýetli hasap edilýän magrupy kişileri grek dilinde gürleşýärdiler. Ýa-da ýokarky gatlaklardan bolan ylymly adamlaryň Puşkin zamanynda nemes, fransuz dilllerinde gepländiklerini oýuňyzda aýlaň. Puşkiniň özem başda goşgularyny fransuz dilinde ýazýardy ahyry. Egerde rus intelligensiýasynyň wekilleri şol ýoluň ýalňyşdygyna wagtynda düşünmedik bolsadylar, onda rus diliniň hem saýry dilleriň aşagynda bireýýämler çüýräp ýa ýok bolup gidäýmegi gaty ahmaldy. Hut şonuň üçinem, soňabaka kadalaşdyrylan, bir bütewi, milli rus dilini emele getirmek barada mesele ýüze çykdy. Ilkibaşda rus diliniň – rýazan şiwesinde goşgy ýazyp ugran S.Ýesenin hem soňra u mumyrus dilinde ýazyp ugrapdy. Rus diliniň häzirki ýagdaýynyňam gaty bir öwerlikli däldigi barada Russiýada şu günki günem az gürrüň gidenok. Mysal üçin, häzirkizaman rus dilinde giňden ulanylýan /hatda bizi