INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (253,1,253,'gezek ýüzbe-ýüz bolup oturandygym üçin, ömürbeýany bilen gyzyklandym. Gerek bolaýar öýden ýerlerimi, ömründäki esasy seneleri ýazyp aaldy. Ine onuň gyzgaça beýany. ...Şamyrat Ýazmuhameow. 1911-nji ýylda Saragt raýonynyň Ikinji Garaman obasynda dogulan. 1929-njy ýylda Mary pedtehnikumynyň ýanyndaky medeniýet işgärlerini taýýarlaýan I ýyllyk kursa girýär we 1930njy ýylda öz obasyna gelip mugallymçylyga başlaýar. 1928-nji ýylda komsomol hataryna girýär. 1939-1942-nji ýyllarda Saragt raýonynyň halk magaryfy bölüminiň müdiri bolup işleýär. 1939-njy ýyldan bäri partiýa çleni. 1940-njy ýylda peduçilişäni gaýybana gutarýar. 1942-nji ýylda fronta gidýär. Leýtnant. Pulemýotçylar wzwodynyň komandiri. Söweşen ýerleri: Dnepretrowskiý, Nikolaýewskiý, Odessa oblastlary. Üçünji ukrain frontuna degişli. Pawlodyr, Dneprodzeržinsk, Apostolowa, Berezinowka, Gulýaý Pole şäherlerini we olaryň töweregindäki ençeme obalary, 1944-nji ýylda Krym azat edilenden soň we üçünji Ukrain fronty, Dördünji Ukrain frontuna birikdirilenden soň bolsa Belorussiýanyň Babrutskiý, Baranowiç, Brest şäherlerini azat etmäge gatnaşan. 1945-nji ýylda ýaradar bolup boşaýar we oba gelip mugallymçylygyny dowam etdirýär. 1951-nji ýylda Çärjewiň pedinstitutyny gaýybana gutarýar. Frontda: ―Watançylyk urşunyň birinji derejeli ordeni‖ bilen we ―Edermenligi üçin‖ diýen medal bilen sylaglanýar. Uruşdan soň: ―Zähmetde tapawutlanandygy üçin‖, ―Zähmetde edermenligi üçin‖ diýen medallar bilen sylaglanýar. Halk magaryfynyň otliçnigi. 1966-njy ýylda TSSR-iň at gazanan mugallymy‖ diýen hormatly ada mynasyp bolýar hem-de hormat haty bile sylaglanýar. 1939-njy ýylda mugallymçylygy hem-de köpçülik işine işeňňir gatnaşandygy üçin, esasanam serhetçilere ýakyndan kömek berendigi üçin, ―Zähmet gyzyl baýdak ordeni‖ bilen sylaglanýar. ... Howwa, gysgaça beýany şeýleräk. Ýöne onuň ömri, geçen ýoly barada ýörüte makala, hem ýazmak mümkin. Bu elbetde gelejegiň işi. Moskwa, dekabr, 1989 ý. “Ýaş kommunist” gazeti 1990 ý.

