INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (257,1,257,'diýen düşünjeden saplanmaklary, sesini çykarman ýören adamlaryň ýüreklerindäki ýanyp duran ody görmekligi başyrmaklary gerek. Üýtgedip gurmak, çaltlandyrmak üçin, sungaty öwrenijileriň hem tijenmekleri gerek. Şu çaka çenli ýekeje hudožnik hakynda ýekeje tankydy makala-da ýazylmady diýsek ýalňyş bolmazmyka diýýän. Bize ýürekden ýazylan, tankydy makalalar, synlar gerek. Hoşniýetli tankyt bilen ýaňsa alynýan, ýörüte ýamanlyk etmek üçin ýazylan tankydyň arasynda çäk goýup bilýän tankytçylar gerek. Işe täzeje çemeleşmek meselesinde hudožnikler üçin iň bir derwaýys mesele hem — žurnal meselesidir. Bize redaksiýa gerek. Öz hususy redaksiýamyzyň bolmagy gerek. Eger-de şeýtsek, biziň ýapyk duran ussahanalarymyzyň böwrüni deşip, diwaryň aňyrsyndaky hyň berip duran halka tarap äpişgejik açdygymyz bolardy. Şeýle žurnalyň aýba-aý däl-de, kwartallaýyn, hatda ýylda iki gezek çykarylmagyna-da biz razy. Ýöne şol žurnalyň hudožnik bilen halkyň aralygynda gaýym köpri bolup hyzmat etjekdigi welin aýdyň zat. Şol žurnal arkaly biziň halk bilen ýüzbe-ýüz gürleşmegimiz we düşünişmegimiz gerek. Dogrusyny aýtsak şu günki gün halk bizi gaty bir ykrar edip baraýanok. Ýa hakykatdanam halk syngata düşünenokmyka? Ony diýseňem olar Rembranda, Rubense, Surikowa, Repine dagy-ha gaty gowy düşünýärler. Klassyklaryň aälisinem gowy görýärler. Ýa biz şolardanam has çylşyrymlyrak işleýärmikäk? Magtymgula düşünýän halkyň iki gözüniň içine seredip: „Sen bize düşüneňok― diýmek bilen biz gaty bir naýynsaplyk edýän-ä däldiris-dä? Biziň özümiz halka düşnüksiz bolan haýsydyr bir ýat dilde gürleýän bolaýmalyň, düşünişip bilmeýän bolaýmalyň? Aramyzda diwar saklaýan bolaýmalyň? Sungatyň „janly organizmdigini―, onuň bir duran ýerinde durup bilmejekdigini, geçirilýän gözlegleriň hemmesiniň uçdantutma hakyky sungat hasap edilmeýändigini, häzirki „haý-haýly― hasap edilýän hudožnikleriňem birenteginiň wagtyň geçmegi bilen 