INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (258,1,258,'nygtaýaryn — bize redaksiýa gerek! Özbaşymyza, içi suratly, tekstli žurnal gerek. Hudožnikler soýuzynyň ýolbaşçy işgärleri bu barada hem örän çynlakaý alada etmelidirler. Soňky wagtlarda hudožnikler soýuzynyň işinde üýtgeşiklik duýulýarmy ýa bar zat öňki durşuna durmy? Elbetde duýulýar. Beýik Oktýabr Sosiýalistik rewalýusiýasynyň ýetmiş ýyllygyna gawatlap, alty-ýedi ýyl bäri haraba dönüp ýatan sergi zalynyň remonty tamamlandy we hudožnikleriň ýubileý sergisi hut şol zalda açyldy. Ýolöten köçesindäki ussahanalara ýyladyş sistemasyny çekmeklik işi tamamlanyp barýar. Ýubileý sergisine iş saýlamak üçin düzülen komissiýa sergi üçin seçiljek işleri tema taýdan çäklendirmezligi göz öňünde tutdy we şonuň netijesinde serginiň gyzykly bolmagyny gazandy. Ýaşlara jogapkärli işler ynanyldy. Hudožnikleriň işjeňligi, göz-görtele artdy. Muny ýübileý sergisine getirilen işleriň sanynyň garaşylyşyndanam has köp bolandygy, seçilen işleriň sergi zalyna sygmandygy sebäpli şol işleri ikä bölüp, serginiň bir bada iki ýerde /hudožnilker soýuzynyň sergi zalynda we HHGS-de/ guralandygy bilenem düşündirse bolar. Ýöne üýtgedip gurmakda hudožnikler soýuzynyň ýolbaşçy işgäleriniň öňünde durýan meseleler, täzeçe çemeleşmegi talap edýän, çözgüdine bikararlyk bilen garaşýan gaýragoýulmasyz çäreler entek sanardan köp. Şolaryň iň ynjygy, iň derwaýysam sergilere iş seçýän sergi komissiýasynyň, çeperçilik sowetleriniň agzalarynyň intellektual derejelrini öňküdenem has ýokary götermekden ybaratdyr. Mysal üçin iş seçiljek wagtynda, sergi ýapylmazynyň öňisyrasynda geçirilýän çekeleşikler, pikir alyşmalar mahalynda awtoryň şahsyýetine degäýjek, ony kemsidip biläýjek ýa özünden göwni geçer ýaly edäýjek sözlerden gaça durmaly.Komissiýanyň içinde bolanyň bilen özüňi ähli adamlardan ýokary tutubermeli däldigine, beýlekilerdenem edil öz göwnüňe gelşiçe, öz duýuşyňça talap edibermeli däldigine, her kimiň kalbynyň g