INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (261,1,261,'Hut şol zatlar sebäplem özüňden öňki iki nesildenem gowşak, iň bolmanda şeýle hasap edilýän üçünji nesil, biziň neslimiz emele geldi. Bizi bökdän zadyň biri şu bolsa, ýene birem deň-duşlarmyzyň sungata täze öwüşgin getirendikleridir. Şu babatda köpleriň biziň bilen ylalaşaslarynyň gelmeýändikleridir. Dogry, men biziň deň-duşlarymyzda ýalňyşlyk bolan däldir diýip biljek däl. Bolandyr. Asyl-ha ýalňyşsyz gözlegem ýokdur. Diňe gözlemeýän adam ýalňyşýan däldir. Goý, oglanlar ýalňyşan bolsunlar, goý olar kimdir birine, aýdaly impressionistlere, ýa abstraksiýaçylara, sýurrealistlere ýa ekspressionistlere öýkünen bolsunler, giý entek olar milli mekdep diýilýän mekdebi döredip bilmedik bolsunler, goý şeýle bolsun, gep onda däl, gep gözlegde. Iň esasy zat olar gözlediler. Şol gözleglerimiziň ýetilen sepgit däldigine maksada tarap barýan ýoluň ujypsyzja bir bölegidine biz şol wagtlaram düşünýärdik, häzirem düşünýäris. Eger-de kimde-kim düşünmeýän bolsa biz onda oňa ýatladyp bileris. Bize günbataryň hiç-hili ―izmi‖ gerek däl. Bize özboluşly, diňe öz ýüzümiz görnüp duran sungat gerek. Amanat zat gerek däl. Sulbaragam bolsa egnimizde goý öz eşigimiz bolsun. Ýöne ýene bir gezek aýdýan, gözlege ýalňyşlyk hökmünde garamak, ýanamak bolmaz. Men bu zatlary kine üçin ýa igenç üçin aýdamok. Men muny tutuş bir hudožnikler nesliniň ykbalyna çykan ümürli howanyň hiç bolman şundan soň bir syrylyp gitmegi üçin aýdýan. Şol zatlaryň täze ýolbaşçylar tarapyndan gaýtalanmazlygy üçin aýdýan. Ýatladýan. Sebäbi biziň yzymyzdanam täze bir nesil ýetişip gelýär. Ine, şolaryň bir şol ―aldawaç tigriň‖ içine düşmezlikleri üçin aýdýan. Hudožnikler soýuzynda dörän agzalaçylygyň düýp sebäbini diňe şolar ýaly zatlardan gözlemelidigini duýdurmak üçin aýdýan. Eýsem Hudožnikler soýuzynda täzeden gurmagy nämeden başlamaly? Aslynda dörediji adamyň aňyny üýtgetmek gerekmi? Mümkinmi? Mümkin! Bize öňi bilen öz aňymyzy g