INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (293,1,293,'1970 35,2 6,6 28,6 1980 34,3 8,3 26,0 1985 36,0 8,1 27,9 1986 36,9 8,4 28,5 1987 36,9 7,9 29 ,0

