INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (299,1,299,'Şu ýerde biziň ýene-de Enejan Aşyrowa bilen eden gürrüňimize dolanasymyz gelýär. Ol galyň bilen baglanyşykly gozgalan işleriň sanynyň 1987-nji ýylda 13 bolandygyndan, 1988-nji ýylda 11-e düşendigini, onuňam sebäbiniň tä iş-işden geçip, gudalaryň arasyna tow düşýänçä, gelin gidip malpul dawasy täzeden tutaşýança hiç kimiňem derňew, sud, organ işgärlerine ýüz tutmaýandyklaryndandygyny gynanç bilen aýtdy. ―Ýa-ha şu zatlaryň barypýatan bidereklikdigine düşünseler, ýa-da wagtyndajyk gelip bize ýüz tutsalar‖ diýip, öwran-öwran janykdy. Dogrudanam şu zatlara her kimiň edil öz enesine kesek atmaly däldigine düşünişi ýaly düşünmegi gerek. Biziňem düşündiriş işlerini güýçlendirmegimiz gerek. Halkyň düşünjesini şol derejä ýetirip bilmesek öz şahsy hereketlerimiz bilen görelde görkezmesek, galan göreşlerimiziň barysy puç. Kimdir biriniň öten agşam telewizorda ýa ýygnakda galyňa garşy gürläp, ertesi agşamam öz eli bilen gyzyna baha kesýändigini görüp halk bize bäribärde ynanmaz. Şonuň üçinem ilki bilen özümizi düzedeliň. Her kim öz-özüni düzedip bilse, hemmäniňem düzeldigi bolar. Häzir welin hemme adam ili düzetjek-de özi şol durşuna galjakdan.

