INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (339,1,339,'çykaryp bolýardy. Ýolbaşça sökdi, partiýa dil ýetirdi diýip, goňşyňy ýa işdeş ýoldaşyňy ýurtdan çykardyp bolýardy. Soňky döwürlerde Prezidentiň Permany bilen: - Hatyra gününi, Nowruz baýramçylygyny bellemek, oba medeniýetini ösdürmek we ýurdy baglyga öwürmek ýaly birnäçe kararlar kabul edildi. Şol kararlar, elbetde, halk köpçüligi tarapyndan gyzgyn goldaw hem tapýar, köp ýerde ak ýürekden durmuşa hem geçirilýär. Emma, gynansak-da, käbir adam bag ekmek meselesine möwsümleýin zat hökmünde garaýar. Indi telewizory açsaňam öňýeten düýbi çala gömlen nahalyň çür başyndan tutup: ―Ine men bag ekdim diýip, gygyryp dur, radiony açsaňam başga biri şol sözi gaýtalap dur. Wah, käşgä şol zatlar jan-tenden edilýän bolsa! Janyň ýanýan ýeri, şu meseläniňem käýerde eýýäm ―haý-haýa‖ öwrülenliginde! Ol baglar soň gögerjekmi, gögermejekmi, onuň bilen hiç kimiň işi ýok. Olar şu wagt hasabat bermeli. Pylança düýp oturtdyk, pylança düýbem oturtjak diýmeli. Özüni kanuny ýerine ýetirmekde ilgezek edip görkezmeli. Ýolbaşçynyň gözüne ilmeli. Oturan kürsüňe bir çüýi artykmaç kakmaly. Ol adam bagyň hossary däl. Öz aladasynyň hossary. ―Haý-haýyň‖ guly. Howwa, öňki dil bilen aýtsak, häzir käbir ýerde ―bag kampaniýasy‖ dowam edýär. Emma hakykatda welin baglar gan eňreşipýärler. Sözümize ten bererin diýseňiz Aşgabadyň köçelerindäki baglara ser salyň. Esasanam çolarak köçelerindäki, demirýoluň uzaboýundaky, ―dostluk‖ alleýasyndaky baglara ser salyň. Bir gowy zat – öňümiz ýaz. Agaçlaryň oýanjak wagty. Olaryň ukudan nähili kynlyk bilen açylyşlaryny, ýarym öli, ýarym diri halda ysgynsyzlyk bilen galyşlaryny synlamaga mümkinçilik bar. Görersiňiz welin baglaryň köpüsi pyntyk ýaryp bilmän aglaşar, gülläp bilmän yzlaşar, ahyrsoňam uruşdan gaýdyp gelen maýyp adam ýaly, döwük-ýenjik şahalaryny aşyklynyň eti deý sallaşyp, ýarpy göwreleri bilen zoraýakdan sudura gelerler. Göm-gök öwsen abat şahalarynyň arasyndaky 