INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (341,1,341,'gezdirmek üçin zenanlarymyzyň asyrlarboýy başyna jyga edip gelen börüklerini, utanç-haýalylygynyň nyşany hökmünde saklap ýören ýaşmaklaryny, bürenjeklerini öz elleri bilen oda atdyrdyk. Kiçi geýimini çykaryp, saçyny kesip, ýüzüne reňk çalyp, orsça geplemäni medeniýetli hasap etdik, başarsa-başarmasa göz üçin uly işlere çekdik, deputat saýladyk. Şeýdip şolaryň üsti bilen döwrebap, gowy görünjek bolduk. Indem gyzlaryň hemmesiniň saçyny iki örüm edip öňünden goýbertmek, mekdeplerde oglanlardan aýratyn okutmak /gör-ä muny! öň-ä zor bilen bile oturdýardylar.../, edep sapagyny ýerde okutmak /eline çybygam alaýsa, tüýs bolaýjak ekeni/, barada radioda, telewizorda gürrüň edilip başlandy. Hatda käbir mekdep direktorlarynyň: ―gyzlardan aktiwlige çekäýmäň, şolardan klaskom, arassa komissiýaň başlygy dagy saýlaýmaň‖ diýip, klas ýolbaşçylaryna ýeke-ýeke /üns beriň, aýratynlykda/ sargap çykýandyklary barada habarlar hem gulagymyza degýär. Gyzam ynsandyr. Heniz mekdep partasynda otyrka beýdip ezij naçaryň göwnüni çökermek gabahatlykdyr. Onuň özündenem beter ejizlemekdir. Gyz terbiýesiniň kynçylygyndan basylyp ony, ýagty ýalançynyň şemalyndan mahrum etmekdir. Gerek wagty biz olary är ornunda ulandyk. Front döwürleri ―Watan üçin‖ diýip traktor sürdürdik. Gazy gazdyrdyk. ―Aýallar kolhozda uly güýçdir‖ diýip, orak ordurdyk, pagta ýygdyrdyk. Soň özümiz piwo, et satýan dükanlara geçip, olara kerpiç guýdurdyk, jaý saldyrdyk. Indem ―geliň şularyň ysy çykmaz ýaly edeliň‖ diýşip, biri-birimiziň gulagymyza pyşyrdaşyp ýörsek, şundan beterem namartlyk bolarmy? Dogry, terbiýe çüpredi. Oňa söz ýok. Aýal-gyzlaryň türkmeniň adyna ysnat getiren ýerlerem, gül ýüzli ýigitleriň ýüzüni ýere salýan ýerlerem az bolmady, ýöne şol ýagdaýdan çykmak üçin gadagançylyga ýüz urmak bolmaz. Olaryň daşyny gabap, ―hatardan çykaryp‖ ýol alyp bolmaz. Özümiz gowy bolsak, öz görüm-göreldämiz gowy bolsa, çagalarymyzam gowy