INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (362,1,362,'Dört sagada golaý uçanymyzdan soň, Irlandiýanyň Şenon uçargähinde gonýarys. Bu ýerde howa 8 gradus maýyl. Uçargähiň zaly dürli harytlardan hyryn-dykyn doldurylan dükanlardan ýaňa gözüň ýagyny alyp barýar ýöne bar zat diňe dollara satylýar. Bizde bolsa o ýok. Seredýäs, emenýäs, aýrylýas. Sagat ýarymdan soň ýene-de göterilýäs. Meşhur Bermut üçbururçlygynyň üsti bilen ylaýyk dört sagat uçup, bu gezek kanadanyň Gonder uçargähine baryp düşýäris. Howa bir gradus sowuk. Bu ýerde-de harydyny dollara satýan dükanjyklar az däl. Biz uçardan düşjek wagtymyz elimize tutdyrylan birkajyga bir banka pepsi-kola alyp bokurdagymyzy ölleýäris. Oňa çenlem uçara münmäge çagyrýarlar. Ýene-de bäş sagat uçup, Gawenanyň ―Hose Marti‖ uçargähinde uçardan çykýarys. Howa 24 gradus maýyl. Mylaýym. Ýumşak. Bizi garşy alan awtobus, Gawananyň on sekiz mertebeden ybarat ―Kapri‖ myhmanhanasynyň işiginde saklanýar. Terjimeçi Marla Sançes bize myhmanhana ýerleşmäge, dokumentleri dolduryşmaga kömek edýär we ertire çenli hoşlaşýar. 2. Ilkinji tanyşlyklar Şäher bilenem, şäheriň adamlary bilenem, Kubaly ýazyjylar bilenem tanyşlyk şol günüň ertesi irden başlandy. Turup, sekizinji mertebede ýerleşýän otagymyzyň äpişgesinden äňedişim ýaly, ilki gözümiň düşen zady – aňyrsyna bärsine göz ýetmeýän ümmülmez gök deňiz boldy. Alyslardan eplem-büklem bolup gelýän tolkunlaryň gara daşlara bagryny oýkap, birdenem öwgüldäp goýberişem, haşyldap uludan demini alyşam eşidilip dur. A-aňyrda bolsa iküç sany ak ýelkenli äpet gämiler görünýär. Olar ýa-ha durlar, ýa-da örän haýal hereket edýärdiler. Şol ýeriň porta girmek üçin garaşylýan ýer bolmagam ahmal. Asman dury. Göm-gök. Ýüzünde ak bulutlar gaýyşyp ýörler. Şeýle asuda howada-da deňziň bolubilenini bolup durşuna geň galýarsyň. Bir keçje ýeri biziň äpişgämizden deňiz doly görnenok. Üçden bir bölegini gabat-garşymyzdaky belent jaý tutup dur. Ertirlik nahardan soň bütin delegas