INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (368,1,368,'Ilçihanada bolan duşuşykda Oswaldo Nawarrony görenimden başlap, tä, Gawanadan gaýdýançam, Kubalylaryň köpüsiniň türkmenlere juda meňzeşdigi meni haýran galdyrdy. Men birsyzly olary öňem bir ýerde gören ýaly boldum durdum. Olaryňam, kä daýym ýoldaşlaryma meni görkezip: – Este es posiblemente un Kuwano?.. – diýip, ýylgyryşan gezekleri az bolmady. Halkynyň häsiýeti gowy. Adamlaram edil öz howalary ýaly. Mylaýym. Hoşgylaw. Ýekeje gezegem gykylyk, galmagal edişip duranlaryna duşmadyk. Nobata dursalaram arkaýyn durlar. Dawa-jenjel ýok. Malekonyň ugry bilen gidip barýansyň. Birdenem çat maňlaýyňdan: – Buýenos dias, kamponýeros! – diýen mylaýym ses eşidiler. Saklanarsyň. Salamlaşarsyň. Bir enaýy ýylgyryp duruşlaryna olar seniň niredendigiňi sorarlar. Gürleşjek bolarlar. Sen: – Sowietik, sowiet union... – diýip, barja bilýänjäňi orta oklarsyň. – O-o russo?.. – No, turkmen... Bolany. Ondan aňyrda sende-de zat ýokdur, olarda-da. Olar welin barybir bir zatlar soraşdyrarlar. Seniň bilen gürleşip bilmeýänine gynanarlar. Ala-ýaz bolşup baryşlaryna ep-esli arany açansoňlaram elllerini bulaýlaşyp: – Asta pronto amigo! – diýşip gygyryşarlar. Käbirleri bolsa, ―sowietik‖ diýeniňden: – O-o, Garbaçýow!.. Perestroýka!.. – diýşip, uly şowhun turuzarlar. Üstüňe sorag baryny ýagdyrarlar. Sen bolsaň ýene-de eliňi serip, egniňi gysyp duransyň.

